// === js/smooth-scroll.js ===
/**
 * UFF Medicina 2027 - Smooth Scroll Físico (Lenis + GSAP ScrollTrigger)
 * Elimina saltos discretos do scroll do mouse e sincroniza 1:1 com GSAP Ticker a 60/120 FPS.
 */
(() => {
    'use strict';

    document.addEventListener('DOMContentLoaded', () => {
        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (prefersReducedMotion || typeof Lenis === 'undefined') {
            window.__lenis = null;
            return;
        }

        const lenis = new Lenis({
            duration: 1.05,
            easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
            orientation: 'vertical',
            gestureOrientation: 'vertical',
            smoothWheel: true,
            wheelMultiplier: 0.95,
            touchMultiplier: 1.4,
            syncTouch: false
        });

        window.__lenis = lenis;

        if (typeof gsap !== 'undefined' && typeof ScrollTrigger !== 'undefined') {
            lenis.on('scroll', ScrollTrigger.update);

            gsap.ticker.add((time) => {
                lenis.raf(time * 1000);
            });
            gsap.ticker.lagSmoothing(0);
        } else {
            function fallbackRaf(time) {
                lenis.raf(time);
                requestAnimationFrame(fallbackRaf);
            }
            requestAnimationFrame(fallbackRaf);
        }
    });
})();

// === js/hero-parallax.js ===
/**
 * UFF Medicina 2027 - Hero Depth Parallax
 * Desktop Mouse Movement + Mobile Gyroscope (DeviceOrientation)
 */
document.addEventListener('DOMContentLoaded', () => {
    const hero = document.getElementById('hero');
    const bgLayer = document.getElementById('hero-bg-layer');
    const textLayer = document.getElementById('hero-text-layer');
    const doctorsLayer = document.getElementById('hero-doctors-layer');

    // -----------------------------------------------------------------
    // CÁLCULO DINÂMICO DE ALTURA E POSIÇÃO DOS MÉDICOS & TÍTULO NO MOBILE
    // Calcula a posição do texto com base na navbar e a altura dos médicos
    // garantindo leitura 100% livre e visual 3D perfeito em qualquer resolução
    // -----------------------------------------------------------------
    function adjustHeroMobileLayout() {
        if (!hero || !textLayer || !doctorsLayer) return;

        if (window.innerWidth >= 768) {
            textLayer.style.top = '';
            textLayer.style.position = '';
            doctorsLayer.style.top = '';
            doctorsLayer.style.height = '';
            return;
        }

        textLayer.style.position = 'relative';
        textLayer.style.top = '0px';

        const heroH = hero.clientHeight || window.innerHeight;
        const titleTop = textLayer.offsetTop;
        const titleHeight = textLayer.offsetHeight || 76;
        const titleBottom = titleTop + titleHeight;

        const doctorsTop = Math.max(100, Math.min(Math.round(heroH * 0.30), titleBottom + 2));
        doctorsLayer.style.top = `${doctorsTop}px`;
        doctorsLayer.style.height = `${Math.max(240, heroH - doctorsTop)}px`;
    }

    adjustHeroMobileLayout();
    if (document.fonts && document.fonts.ready) {
        document.fonts.ready.then(adjustHeroMobileLayout).catch(() => {});
    }
    window.addEventListener('load', adjustHeroMobileLayout, { once: true });
    window.addEventListener('resize', adjustHeroMobileLayout, { passive: true });
    window.addEventListener('orientationchange', () => {
        setTimeout(adjustHeroMobileLayout, 100);
    }, { passive: true });

    if (typeof gsap === 'undefined') return;
    if (typeof ScrollTrigger !== 'undefined') {
        gsap.registerPlugin(ScrollTrigger);
    }

    // Subtle Depth Parallax between the 3 stacked planes (Desktop Mouse + Mobile Gyroscope)
    if (hero && bgLayer && textLayer && doctorsLayer) {
        // Desktop Mouse Parallax (otimizado com gsap.quickTo e suspenso durante o scroll)
        const setBgX = gsap.quickTo(bgLayer, 'x', { duration: 0.9, ease: 'power2.out' });
        const setBgY = gsap.quickTo(bgLayer, 'y', { duration: 0.9, ease: 'power2.out' });
        const setTextX = gsap.quickTo(textLayer, 'x', { duration: 0.8, ease: 'power2.out' });
        const setTextY = gsap.quickTo(textLayer, 'y', { duration: 0.8, ease: 'power2.out' });
        const setDocX = gsap.quickTo(doctorsLayer, 'x', { duration: 0.7, ease: 'power2.out' });
        const setDocY = gsap.quickTo(doctorsLayer, 'y', { duration: 0.7, ease: 'power2.out' });

        hero.addEventListener('mousemove', (e) => {
            if (window.pageYOffset > 10) return;

            const x = (e.clientX / window.innerWidth - 0.5);
            const y = (e.clientY / window.innerHeight - 0.5);

            setBgX(-x * 12);
            setBgY(-y * 8);
            setTextX(x * 18);
            setTextY(y * 10);
            setDocX(x * 32);
            setDocY(y * 14);
        }, { passive: true });

        hero.addEventListener('mouseleave', () => {
            if (window.pageYOffset > 10) return;
            setBgX(0);
            setBgY(0);
            setTextX(0);
            setTextY(0);
            setDocX(0);
            setDocY(0);
        });

        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        if (!prefersReducedMotion) {
            let isHeroVisible = true;
            if ('IntersectionObserver' in window) {
                const heroObserver = new IntersectionObserver((entries) => {
                    isHeroVisible = entries[0].isIntersecting;
                }, { threshold: 0.05 });
                heroObserver.observe(hero);
            }

            let initialBeta = null;
            let initialGamma = null;
            let orientationActive = false;

            const handleOrientation = (e) => {
                if (!isHeroVisible || e.beta === null || e.gamma === null) return;

                if (initialBeta === null) {
                    initialBeta = e.beta;
                    initialGamma = e.gamma;
                }

                const rawDeltaX = (e.gamma - initialGamma) / 18;
                const rawDeltaY = (e.beta - initialBeta) / 18;

                const deltaX = Math.max(-1, Math.min(1, rawDeltaX));
                const deltaY = Math.max(-1, Math.min(1, rawDeltaY));

                initialBeta += (e.beta - initialBeta) * 0.015;
                initialGamma += (e.gamma - initialGamma) * 0.015;

                const isMobile = window.innerWidth < 768;
                if (isMobile) return;

                const docDisplaceX = deltaX * 36;
                const docDisplaceY = deltaY * 16;
                const textDisplaceX = deltaX * 20;
                const textDisplaceY = deltaY * 12;
                const bgDisplaceX = -deltaX * 14;
                const bgDisplaceY = -deltaY * 10;

                gsap.to(bgLayer, { 
                    x: bgDisplaceX, 
                    y: bgDisplaceY, 
                    scale: 1.03, 
                    duration: 0.7, 
                    ease: 'power2.out', 
                    overwrite: 'auto' 
                });
                gsap.to(textLayer, { 
                    x: textDisplaceX, 
                    y: textDisplaceY, 
                    duration: 0.65, 
                    ease: 'power2.out', 
                    overwrite: 'auto' 
                });
                gsap.to(doctorsLayer, { 
                    x: docDisplaceX, 
                    y: docDisplaceY, 
                    duration: 0.55, 
                    ease: 'power2.out', 
                    overwrite: 'auto' 
                });
            };

            window.addEventListener('orientationchange', () => {
                initialBeta = null;
                initialGamma = null;
            });

            const requestOrientationPermission = () => {
                if (orientationActive) return;

                if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
                    DeviceOrientationEvent.requestPermission()
                        .then(permissionState => {
                            if (permissionState === 'granted') {
                                orientationActive = true;
                                window.addEventListener('deviceorientation', handleOrientation, { passive: true });
                            }
                        })
                        .catch(() => {});
                } else if ('DeviceOrientationEvent' in window) {
                    orientationActive = true;
                    window.addEventListener('deviceorientation', handleOrientation, { passive: true });
                }
            };

            if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission !== 'function') {
                requestOrientationPermission();
            }

            const enableOnFirstGesture = () => {
                requestOrientationPermission();
                window.removeEventListener('touchend', enableOnFirstGesture);
                window.removeEventListener('click', enableOnFirstGesture);
            };
            window.addEventListener('touchend', enableOnFirstGesture, { once: true, passive: true });
            window.addEventListener('click', enableOnFirstGesture, { once: true });
        }
    }
});

// === js/scrolly-jaleco.js ===
/**
 * UFF Medicina 2027 - Hero Parallax Exit & Scrollytelling do Jaleco
 * Saída natural do Hero com paralaxe multi-plano + pinagem dedicada aos 48 keyframes do médico
 * Sorteio aleatório feminino/masculino + 4 pilares informativos
 */
document.addEventListener('DOMContentLoaded', () => {
    if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return;
    
    const hero = document.getElementById('hero');
    const bgLayer = document.getElementById('hero-bg-layer');
    const textLayer = document.getElementById('hero-text-layer');
    const doctorsLayer = document.getElementById('hero-doctors-layer');

                ScrollTrigger.config({ ignoreMobileResize: true });

                const scrollyStage = document.getElementById('scrolly-stage');
                const isMobileScroll = window.innerWidth < 768;

                if (scrollyStage) {
                    const TOTAL_FRAMES = 48;
                    const FRAMES = new Array(TOTAL_FRAMES).fill(null);

                    // 4 Sprite Sheets intercalados (3x4 = 12 frames por arquivo, 4 requests totais)
                    // O Sheet 0 já cobre do frame 0 ao 47 (100% da animação disponível logo no 1º request!)
                    const SHEET_SLOTS = [
                        [0, 4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 47],
                        [2, 6, 10, 14, 18, 22, 26, 30, 34, 38, 42, 45],
                        [1, 5, 9, 13, 17, 21, 25, 29, 33, 37, 41, 44],
                        [3, 7, 11, 15, 19, 23, 27, 31, 35, 39, 43, 46]
                    ];

                    // Sorteio aleatório a cada recarregamento (50% mulher / 50% homem)
                    const currentGender = Math.random() < 0.5 ? 'female' : 'male';
                    const canvas = document.getElementById('scrolly-canvas');
                    const ctx = canvas ? canvas.getContext('2d', { alpha: true }) : null;
                    if (ctx) {
                        ctx.imageSmoothingEnabled = true;
                        ctx.imageSmoothingQuality = 'high';
                    }
                    // Cache de geometria do canvas para zero cálculos matemáticos por frame de scroll
                    let cachedW = 0;
                    let cachedH = 0;
                    let cachedDrawW = 0;
                    let cachedDrawH = 0;
                    let cachedOffsetX = 0;
                    let cachedOffsetY = 0;

                    // Elementos do HUD de Progresso e Navegação Rápida
                    const scrollyHud = document.getElementById('scrolly-hud');
                    const scrollyProgressBar = document.getElementById('scrolly-progress-bar');
                    const scrollyScrollCue = document.getElementById('scrolly-scroll-cue');

                    if (scrollyScrollCue) {
                        scrollyScrollCue.addEventListener('click', (e) => {
                            e.preventDefault();
                            const vagas = document.getElementById('vagas');
                            if (!vagas) return;
                            if (window.__lenis) {
                                window.__lenis.scrollTo(vagas, { duration: 1.1 });
                            } else {
                                vagas.scrollIntoView({ behavior: 'smooth' });
                            }
                        });
                    }

                    // ==========================================================
                    // MOTOR DE INTERPOLAÇÃO SUAVE DESACOPLADA (LERP ASSISTIDO EM rAF)
                    // Sincronizado ao Lenis Smooth Scroll para resposta imediata e 60/120 FPS.
                    // ==========================================================
                    let targetFrame = 0;
                    let smoothFrame = 0;
                    let displayedIndex = -1;
                    let displayedSourceIndex = -1;
                    let isLoopRunning = false;

                    function isFrameReady(item) {
                        if (!item) return false;
                        if (item.sheet) {
                            return Boolean(item.sheet.complete && item.sheet.naturalWidth > 0);
                        }
                        if (typeof ImageBitmap !== 'undefined' && item instanceof ImageBitmap) {
                            return item.width > 0;
                        }
                        return Boolean(item.complete && item.naturalWidth > 0);
                    }

                    function getReadyFrameEntry(index) {
                        const clamped = Math.max(0, Math.min(TOTAL_FRAMES - 1, index));

                        if (isFrameReady(FRAMES[clamped])) {
                            return { item: FRAMES[clamped], index: clamped };
                        }
                        for (let offset = 1; offset < TOTAL_FRAMES; offset++) {
                            const prev = clamped - offset;
                            if (prev >= 0 && isFrameReady(FRAMES[prev])) {
                                return { item: FRAMES[prev], index: prev };
                            }
                            const next = clamped + offset;
                            if (next < TOTAL_FRAMES && isFrameReady(FRAMES[next])) {
                                return { item: FRAMES[next], index: next };
                            }
                        }
                        return null;
                    }

                    function drawFrame(item, sourceIdx) {
                        if (!canvas || !ctx || !item) return;
                        ctx.clearRect(0, 0, cachedW, cachedH);
                        if (item.sheet) {
                            ctx.drawImage(
                                item.sheet,
                                item.sx, item.sy, item.sw, item.sh,
                                cachedOffsetX, cachedOffsetY, cachedDrawW, cachedDrawH
                            );
                        } else {
                            ctx.drawImage(item, cachedOffsetX, cachedOffsetY, cachedDrawW, cachedDrawH);
                        }
                        if (typeof sourceIdx === 'number') {
                            displayedSourceIndex = sourceIdx;
                        }
                    }

                    function tickSmoothFrames() {
                        const diff = targetFrame - smoothFrame;

                        if (Math.abs(diff) > 0.04) {
                            const speed = Math.abs(diff) > 6 ? 0.34 : 0.24;
                            smoothFrame += diff * speed;
                            const nextIdx = Math.round(smoothFrame);

                            if (nextIdx !== displayedIndex) {
                                displayedIndex = nextIdx;
                                const entry = getReadyFrameEntry(nextIdx);
                                if (entry) drawFrame(entry.item, entry.index);
                            }
                            requestAnimationFrame(tickSmoothFrames);
                        } else {
                            smoothFrame = targetFrame;
                            const finalIdx = Math.round(smoothFrame);
                            if (finalIdx !== displayedIndex) {
                                displayedIndex = finalIdx;
                                const entry = getReadyFrameEntry(finalIdx);
                                if (entry) drawFrame(entry.item, entry.index);
                            }
                            isLoopRunning = false;
                        }
                    }

                    function updateTargetFrame(val) {
                        targetFrame = Math.max(0, Math.min(TOTAL_FRAMES - 1, val));
                        if (!isLoopRunning) {
                            isLoopRunning = true;
                            requestAnimationFrame(tickSmoothFrames);
                        }
                    }

                    function resizeDoctorCanvas() {
                        if (!canvas) return;
                        const rect = canvas.getBoundingClientRect();
                        const dpr = Math.min(window.devicePixelRatio || 1, 2);
                        canvas.width = Math.round(rect.width * dpr);
                        canvas.height = Math.round(rect.height * dpr);

                        cachedW = canvas.width;
                        cachedH = canvas.height;

                        const isMobile = window.innerWidth < 768;
                        const targetHeightRatio = isMobile ? 0.80 : 0.86;
                        cachedDrawH = cachedH * targetHeightRatio;
                        // Proporção exata 16:9 dos frames
                        cachedDrawW = (1600 / 900) * cachedDrawH;
                        cachedOffsetX = (cachedW - cachedDrawW) / 2;
                        cachedOffsetY = cachedH - cachedDrawH;

                        // Sincroniza o wrapper da fita Canvas 2D com bleed superior para os glifos na coroa da cabeça
                        const contourWrap = document.getElementById('scrolly-contour-wrap');
                        if (contourWrap && rect.width > 0 && rect.height > 0) {
                            const cssDrawH = rect.height * targetHeightRatio;
                            const cssDrawW = (1600 / 900) * cssDrawH;
                            const cssOffsetX = (rect.width - cssDrawW) / 2;
                            const cssOffsetY = rect.height - cssDrawH;
                            const cssTopBleed = (cssDrawH / 900) * CONTOUR_TOP_BLEED;

                            contourWrap.style.left = `${cssOffsetX}px`;
                            contourWrap.style.top = `${cssOffsetY - cssTopBleed}px`;
                            contourWrap.style.width = `${cssDrawW}px`;
                            contourWrap.style.height = `${cssDrawH + cssTopBleed}px`;

                            if (contourCanvas) {
                                const cDpr = Math.min(window.devicePixelRatio || 1, 1.5);
                                contourCanvas.width = Math.max(1, Math.round(cssDrawW * cDpr));
                                contourCanvas.height = Math.max(1, Math.round((cssDrawH + cssTopBleed) * cDpr));
                                contourScale = contourCanvas.width / 1600;
                                drawContourRibbon();
                            }
                        }

                        const entry = getReadyFrameEntry(Math.round(smoothFrame));
                        if (entry) drawFrame(entry.item, entry.index);
                    }

                    // ==========================================================
                    // CARREGAMENTO VIA SPRITE SHEET ATLAS + RECORTE GPU (4 REQUESTS TOTAIS)
                    // Reduz 94 requisições para 4 arquivos pré-escalados (desktop 1280x720 / mobile 768x432)
                    // e libera o atlas da VRAM logo após fatiar os ImageBitmaps.
                    // ==========================================================
                    const deviceMemory = navigator.deviceMemory || 8;
                    const saveData = Boolean(navigator.connection && navigator.connection.saveData);
                    const useMobileTier = isMobileScroll || deviceMemory <= 2 || saveData;
                    const sheetTier = useMobileTier ? 'mobile' : 'desktop';
                    const cellW = useMobileTier ? 768 : 1280;
                    const cellH = useMobileTier ? 432 : 720;

                    function loadSheetViaImage(url) {
                        return new Promise((resolve, reject) => {
                            const img = new Image();
                            img.decoding = 'async';
                            img.onload = async () => {
                                if (typeof img.decode === 'function') await img.decode().catch(() => {});
                                resolve(img);
                            };
                            img.onerror = reject;
                            img.src = url;
                        });
                    }

                    async function sliceSheetIntoFrames(source, sheetIndex) {
                        const slots = SHEET_SLOTS[sheetIndex];
                        if (typeof createImageBitmap === 'function') {
                            try {
                                const bitmaps = await Promise.all(
                                    slots.map((_, pos) => {
                                        const sx = (pos % 3) * cellW;
                                        const sy = Math.floor(pos / 3) * cellH;
                                        return createImageBitmap(source, sx, sy, cellW, cellH);
                                    })
                                );
                                if (typeof source.close === 'function') source.close();
                                slots.forEach((frameIdx, pos) => {
                                    FRAMES[frameIdx] = bitmaps[pos];
                                });
                                return;
                            } catch (_) {
                                // Fallback abaixo para recorte direto no drawImage
                            }
                        }

                        slots.forEach((frameIdx, pos) => {
                            FRAMES[frameIdx] = {
                                sheet: source,
                                sx: (pos % 3) * cellW,
                                sy: Math.floor(pos / 3) * cellH,
                                sw: cellW,
                                sh: cellH
                            };
                        });
                    }

                    function refreshCanvasAfterSheetLoad() {
                        if (isLoopRunning) return;
                        const currentTargetIdx = Math.round(smoothFrame);
                        const best = getReadyFrameEntry(currentTargetIdx);
                        if (!best) return;

                        if (displayedIndex === -1 || best.index !== displayedSourceIndex) {
                            const prevDist = displayedSourceIndex === -1
                                ? Infinity
                                : Math.abs(currentTargetIdx - displayedSourceIndex);
                            const newDist = Math.abs(currentTargetIdx - best.index);
                            if (displayedIndex === -1 || newDist < prevDist) {
                                displayedIndex = currentTargetIdx;
                                drawFrame(best.item, best.index);
                            }
                        }
                    }

                    async function loadSheet(sheetIndex) {
                        const url = `assets/transformation/sheets/${currentGender}/${sheetTier}_${sheetIndex}.webp`;
                        let source = null;

                        if (typeof createImageBitmap === 'function') {
                            try {
                                const res = await fetch(url, sheetIndex === 0 ? { priority: 'high' } : undefined);
                                if (!res.ok) throw new Error('HTTP ' + res.status);
                                const blob = await res.blob();
                                source = await createImageBitmap(blob);
                            } catch (_) {
                                source = await loadSheetViaImage(url);
                            }
                        } else {
                            source = await loadSheetViaImage(url);
                        }

                        await sliceSheetIntoFrames(source, sheetIndex);
                        refreshCanvasAfterSheetLoad();
                    }

                    // ==========================================================
                    // FITA TIPOGRÁFICA ANIMADA EM CONTORNO (CANVAS 2D + LUT + SPRITE ATLAS)
                    // Substitui textPath SVG + drop-shadow CSS por sprites 2x pré-renderizados,
                    // eliminando 100% do layout de texto SVG e blur shaders por frame.
                    // ==========================================================
                    const SILHOUETTE_PATHS = {
                        female: 'M 560.2 927.4 C 563.7 909.9, 582.7 852.2, 580.9 822.3 C 579.1 792.4, 565.4 770.1, 549.5 748.1 C 533.6 726.1, 496.5 713.7, 485.3 690.4 C 474.2 667.0, 479.5 634.0, 482.6 608.1 C 485.6 582.2, 495.2 560.4, 503.5 534.8 C 511.9 509.2, 521.4 480.7, 532.5 454.6 C 543.6 428.4, 552.9 399.8, 570.0 377.9 C 587.2 356.0, 620.2 343.9, 635.4 323.1 C 650.5 302.3, 654.2 279.0, 661.0 253.0 C 667.7 227.0, 669.1 194.9, 676.0 167.0 C 682.9 139.2, 690.1 111.1, 702.6 85.8 C 715.1 60.6, 732.7 28.5, 751.1 15.5 C 769.5 2.4, 793.7 -1.8, 813.1 7.5 C 832.5 16.8, 852.3 47.9, 867.4 71.4 C 882.6 94.9, 895.2 121.3, 904.2 148.4 C 913.2 175.4, 914.7 207.3, 921.3 233.5 C 927.9 259.7, 928.8 284.7, 943.6 305.6 C 958.4 326.5, 992.5 337.5, 1010.2 358.9 C 1027.9 380.2, 1038.7 407.8, 1050.0 433.8 C 1061.3 459.7, 1070.3 488.5, 1077.9 514.4 C 1085.5 540.3, 1091.4 562.8, 1095.5 589.1 C 1099.7 615.4, 1110.3 647.0, 1102.8 672.5 C 1095.3 697.9, 1067.2 718.6, 1050.3 741.7 C 1033.5 764.8, 1007.6 780.1, 1001.8 811.1 C 996.0 842.2, 1013.2 908.4, 1015.5 927.8',
                        male: 'M 563.3 923.8 C 553.9 907.9, 526.8 856.1, 506.6 828.3 C 486.5 800.6, 457.7 783.4, 442.4 757.3 C 427.2 731.1, 415.3 700.3, 414.9 671.5 C 414.5 642.7, 431.8 611.8, 440.3 584.6 C 448.9 557.5, 455.7 534.9, 466.1 508.5 C 476.5 482.1, 487.0 451.1, 502.9 426.1 C 518.8 401.1, 537.9 375.7, 561.5 358.6 C 585.1 341.4, 624.5 339.7, 644.4 323.2 C 664.2 306.8, 676.8 285.1, 680.7 259.8 C 684.7 234.4, 667.1 200.8, 668.2 171.1 C 669.2 141.4, 675.2 108.2, 686.9 81.3 C 698.6 54.5, 718.1 22.4, 738.5 10.2 C 758.9 -2.0, 788.4 -3.2, 809.2 8.2 C 830.0 19.6, 851.0 51.9, 863.4 78.5 C 875.9 105.0, 881.9 137.8, 883.9 167.6 C 885.8 197.4, 869.6 232.4, 875.1 257.3 C 880.5 282.3, 895.9 301.7, 916.8 317.4 C 937.7 333.1, 976.3 334.6, 1000.2 351.5 C 1024.1 368.5, 1043.9 394.0, 1060.2 419.0 C 1076.4 443.9, 1087.4 474.6, 1097.8 501.0 C 1108.2 527.5, 1113.9 550.5, 1122.5 577.6 C 1131.1 604.7, 1147.9 635.1, 1149.4 663.9 C 1150.8 692.7, 1144.1 723.8, 1131.0 750.3 C 1118.0 776.9, 1093.1 794.5, 1071.0 823.1 C 1048.9 851.8, 1010.4 905.7, 998.2 922.2'
                    };

                    const contourCanvas = document.getElementById('scrolly-contour-canvas');
                    const contourCtx = contourCanvas ? contourCanvas.getContext('2d', { alpha: true }) : null;
                    const CONTOUR_TOP_BLEED = 44;
                    const LUT_STEP = 2;
                    let lutX = null;
                    let lutY = null;
                    let lutA = null;
                    let lutLen = 0;
                    let lutTotalLen = 0;
                    let contourScale = 1;

                    function buildBezierLUT(dStr) {
                        const tokens = dStr.match(/[MC]|-?\d+(?:\.\d+)?/g);
                        if (!tokens || tokens.length < 3) return;
                        let i = 0;
                        let cx = 0;
                        let cy = 0;
                        const rawX = [];
                        const rawY = [];
                        const rawD = [0];
                        let total = 0;
                        const SAMPLES_PER_SEG = 24;

                        while (i < tokens.length) {
                            const tok = tokens[i++];
                            if (tok === 'M') {
                                cx = parseFloat(tokens[i++]);
                                cy = parseFloat(tokens[i++]);
                                rawX.push(cx);
                                rawY.push(cy);
                            } else if (tok === 'C') {
                                const x1 = parseFloat(tokens[i++]);
                                const y1 = parseFloat(tokens[i++]);
                                const x2 = parseFloat(tokens[i++]);
                                const y2 = parseFloat(tokens[i++]);
                                const x3 = parseFloat(tokens[i++]);
                                const y3 = parseFloat(tokens[i++]);
                                let prevX = cx;
                                let prevY = cy;
                                for (let s = 1; s <= SAMPLES_PER_SEG; s++) {
                                    const t = s / SAMPLES_PER_SEG;
                                    const mt = 1 - t;
                                    const mt2 = mt * mt;
                                    const t2 = t * t;
                                    const px = mt2 * mt * cx + 3 * mt2 * t * x1 + 3 * mt * t2 * x2 + t2 * t * x3;
                                    const py = mt2 * mt * cy + 3 * mt2 * t * y1 + 3 * mt * t2 * y2 + t2 * t * y3;
                                    total += Math.hypot(px - prevX, py - prevY);
                                    rawX.push(px);
                                    rawY.push(py);
                                    rawD.push(total);
                                    prevX = px;
                                    prevY = py;
                                }
                                cx = x3;
                                cy = y3;
                            }
                        }

                        lutTotalLen = total;
                        lutLen = Math.floor(total / LUT_STEP) + 1;
                        lutX = new Float32Array(lutLen);
                        lutY = new Float32Array(lutLen);
                        lutA = new Float32Array(lutLen);

                        let rIdx = 0;
                        for (let k = 0; k < lutLen; k++) {
                            const targetD = k * LUT_STEP;
                            while (rIdx < rawD.length - 2 && rawD[rIdx + 1] < targetD) {
                                rIdx++;
                            }
                            const segLen = rawD[rIdx + 1] - rawD[rIdx];
                            const ratio = segLen > 0 ? (targetD - rawD[rIdx]) / segLen : 0;
                            lutX[k] = rawX[rIdx] + (rawX[rIdx + 1] - rawX[rIdx]) * ratio;
                            lutY[k] = rawY[rIdx] + (rawY[rIdx + 1] - rawY[rIdx]) * ratio;
                        }

                        for (let k = 0; k < lutLen; k++) {
                            const k0 = Math.max(0, k - 2);
                            const k1 = Math.min(lutLen - 1, k + 2);
                            lutA[k] = Math.atan2(lutY[k1] - lutY[k0], lutX[k1] - lutX[k0]);
                        }
                    }

                    const contourUnit = '✦\u00A0TORNE-SE\u00A0ESPECIALISTA\u00A0✦\u00A0PÓS-GRADUAÇÃO\u00A0UFF\u00A0';
                    const ATLAS_SUPERSAMPLE = 2;
                    const ATLAS_FONT_SIZE = 21;
                    const ATLAS_LETTER_SPACING = ATLAS_FONT_SIZE * 0.18;
                    const ATLAS_FONT = `800 ${ATLAS_FONT_SIZE}px "Plus Jakarta Sans", system-ui, sans-serif`;
                    const ATLAS_PAD_X = 12;
                    const ATLAS_CELL_H = 64;
                    const ATLAS_BASELINE_Y = 38;

                    let atlasCanvas = null;
                    let glyphSeq = [];
                    let contourUnitLength = 671.8;
                    let contourOffset = 0;

                    function bakeGlyphAtlas() {
                        const probe = document.createElement('canvas');
                        const pCtx = probe.getContext('2d');
                        if (!pCtx) return;

                        pCtx.font = ATLAS_FONT;
                        const glyphMap = {};
                        const uniqueChars = Array.from(new Set(Array.from(contourUnit)));
                        let curX = 0;

                        for (let i = 0; i < uniqueChars.length; i++) {
                            const ch = uniqueChars[i];
                            const isSpace = ch === ' ' || ch === '\u00A0';
                            const rawW = Math.max(isSpace ? 5.5 : 4, pCtx.measureText(ch).width);
                            const adv = rawW + ATLAS_LETTER_SPACING;
                            if (isSpace) {
                                glyphMap[ch] = { ch, isSpace: true, rawW, halfW: rawW * 0.5, adv };
                            } else {
                                const boxW = Math.ceil(rawW) + ATLAS_PAD_X * 2;
                                glyphMap[ch] = {
                                    ch,
                                    isSpace: false,
                                    sx: curX,
                                    boxW,
                                    srcX: curX * ATLAS_SUPERSAMPLE,
                                    srcW: boxW * ATLAS_SUPERSAMPLE,
                                    srcH: ATLAS_CELL_H * ATLAS_SUPERSAMPLE,
                                    rawW,
                                    halfW: rawW * 0.5,
                                    adv
                                };
                                curX += boxW + 4;
                            }
                        }

                        const aCanvas = document.createElement('canvas');
                        aCanvas.width = Math.max(1, curX * ATLAS_SUPERSAMPLE);
                        aCanvas.height = ATLAS_CELL_H * ATLAS_SUPERSAMPLE;
                        const aCtx = aCanvas.getContext('2d');
                        if (!aCtx) return;

                        aCtx.scale(ATLAS_SUPERSAMPLE, ATLAS_SUPERSAMPLE);
                        aCtx.font = ATLAS_FONT;
                        aCtx.textBaseline = 'alphabetic';
                        aCtx.textAlign = 'left';
                        aCtx.fillStyle = '#FFFFFF';
                        aCtx.shadowColor = 'rgba(0, 0, 0, 0.72)';
                        aCtx.shadowBlur = 7;
                        aCtx.shadowOffsetX = 0;
                        aCtx.shadowOffsetY = 2;

                        for (let i = 0; i < uniqueChars.length; i++) {
                            const g = glyphMap[uniqueChars[i]];
                            if (!g.isSpace) {
                                aCtx.fillText(g.ch, g.sx + ATLAS_PAD_X, ATLAS_BASELINE_Y);
                            }
                        }

                        atlasCanvas = aCanvas;
                        glyphSeq = Array.from(contourUnit).map((ch) => glyphMap[ch]);
                        contourUnitLength = glyphSeq.reduce((sum, g) => sum + g.adv, 0) || 671.8;
                    }

                    function drawContourRibbon() {
                        if (!contourCtx || !contourCanvas || !atlasCanvas || !lutLen || contourCanvas.width === 0) return;

                        const scale = contourScale;
                        contourCtx.setTransform(1, 0, 0, 1, 0, 0);
                        contourCtx.clearRect(0, 0, contourCanvas.width, contourCanvas.height);

                        const TWO_PI = Math.PI * 2;
                        const seqLen = glyphSeq.length;
                        const maxIdx = lutLen - 1;
                        let s = contourOffset;
                        let guard = 0;

                        while (s < lutTotalLen && guard++ < 600) {
                            for (let j = 0; j < seqLen && s < lutTotalLen; j++) {
                                const g = glyphSeq[j];
                                if (!g.isSpace && s + g.rawW > 0) {
                                    const sMid = s + g.halfW;
                                    if (sMid >= 0 && sMid <= lutTotalLen) {
                                        const f = sMid / LUT_STEP;
                                        const i0 = Math.floor(f);
                                        const i1 = i0 < maxIdx ? i0 + 1 : maxIdx;
                                        const frac = f - i0;

                                        const px = lutX[i0] + (lutX[i1] - lutX[i0]) * frac;
                                        const py = lutY[i0] + (lutY[i1] - lutY[i0]) * frac;
                                        let da = lutA[i1] - lutA[i0];
                                        if (da > Math.PI) da -= TWO_PI;
                                        else if (da < -Math.PI) da += TWO_PI;
                                        const ang = lutA[i0] + da * frac;

                                        const cos = Math.cos(ang);
                                        const sin = Math.sin(ang);
                                        contourCtx.setTransform(
                                            cos * scale,
                                            sin * scale,
                                            -sin * scale,
                                            cos * scale,
                                            px * scale,
                                            (py + CONTOUR_TOP_BLEED) * scale
                                        );
                                        contourCtx.drawImage(
                                            atlasCanvas,
                                            g.srcX, 0, g.srcW, g.srcH,
                                            -(ATLAS_PAD_X + g.halfW), -ATLAS_BASELINE_Y, g.boxW, ATLAS_CELL_H
                                        );
                                    }
                                }
                                s += g.adv;
                            }
                        }

                        contourCtx.setTransform(1, 0, 0, 1, 0, 0);
                    }

                    if (contourCanvas && contourCtx && SILHOUETTE_PATHS[currentGender]) {
                        buildBezierLUT(SILHOUETTE_PATHS[currentGender]);
                        bakeGlyphAtlas();

                        if (document.fonts && document.fonts.ready) {
                            document.fonts.ready.then(() => {
                                bakeGlyphAtlas();
                                drawContourRibbon();
                            });
                        }

                        let lastScrollPos = window.scrollY || window.pageYOffset || 0;
                        let scrollSpeed = 0;

                        if (window.__lenis) {
                            window.__lenis.on('scroll', (e) => {
                                if (typeof e.velocity === 'number') {
                                    scrollSpeed = e.velocity * 0.4;
                                }
                            });
                        } else {
                            window.addEventListener('scroll', () => {
                                const currentY = window.scrollY || window.pageYOffset || 0;
                                scrollSpeed = (currentY - lastScrollPos) * 0.35;
                                lastScrollPos = currentY;
                            }, { passive: true });
                        }

                        const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
                        const baseSpeed = prefersReducedMotion ? 0 : 0.85;
                        let isContourVisible = true;
                        let contourRafId = null;

                        function tickContourRibbon() {
                            if (!isContourVisible || document.hidden || prefersReducedMotion) {
                                contourRafId = null;
                                return;
                            }

                            const step = baseSpeed + scrollSpeed;
                            scrollSpeed *= 0.88;
                            if (Math.abs(scrollSpeed) < 0.01) scrollSpeed = 0;

                            contourOffset -= step;

                            if (contourUnitLength > 0) {
                                while (contourOffset <= -contourUnitLength) {
                                    contourOffset += contourUnitLength;
                                }
                                while (contourOffset > 0) {
                                    contourOffset -= contourUnitLength;
                                }
                            }

                            drawContourRibbon();
                            contourRafId = requestAnimationFrame(tickContourRibbon);
                        }

                        function startContourLoop() {
                            if (prefersReducedMotion) {
                                drawContourRibbon();
                                return;
                            }
                            if (isContourVisible && !document.hidden && contourRafId === null) {
                                contourRafId = requestAnimationFrame(tickContourRibbon);
                            }
                        }

                        if ('IntersectionObserver' in window) {
                            const stageObserver = new IntersectionObserver((entries) => {
                                isContourVisible = Boolean(entries[0] && entries[0].isIntersecting);
                                if (isContourVisible) {
                                    drawContourRibbon();
                                    startContourLoop();
                                } else if (contourRafId !== null) {
                                    cancelAnimationFrame(contourRafId);
                                    contourRafId = null;
                                }
                            }, { threshold: 0.01 });
                            stageObserver.observe(scrollyStage);
                        }

                        document.addEventListener('visibilitychange', () => {
                            if (document.hidden && contourRafId !== null) {
                                cancelAnimationFrame(contourRafId);
                                contourRafId = null;
                            } else if (!document.hidden && isContourVisible) {
                                startContourLoop();
                            }
                        });

                        startContourLoop();
                    }

                    window.addEventListener('resize', resizeDoctorCanvas, { passive: true });
                    resizeDoctorCanvas();

                    // Sheet 0 exclusivo primeiro (0% -> 100% em 1 request), depois 1, depois 2 e 3 em paralelo
                    (async () => {
                        try {
                            await loadSheet(0);
                            await loadSheet(1);
                            await Promise.all([loadSheet(2), loadSheet(3)]);
                        } catch (_) {
                            // Silencioso caso algum request seja interrompido em navegação
                        }
                    })();

                    const frameProxy = { frame: 0 };

                    // ==========================================================
                    // 1. SAÍDA NATURAL DO HERO COM PARALAXE MULTI-PLANO AO ROLAR
                    // Usa yPercent/scale/opacity (não colide com x/y do mousemove em hero-parallax.js)
                    // ==========================================================
                    if (hero) {
                        const heroExitTl = gsap.timeline({
                            scrollTrigger: {
                                trigger: hero,
                                start: 'top top',
                                end: 'bottom top',
                                scrub: true,
                                invalidateOnRefresh: true
                            }
                        });

                        if (bgLayer) {
                            heroExitTl.to(bgLayer, {
                                yPercent: 22,
                                scale: 1.07,
                                opacity: 0.35,
                                ease: 'none',
                                duration: 1
                            }, 0);
                        }
                        if (textLayer) {
                            heroExitTl.to(textLayer, {
                                yPercent: 34,
                                scale: 0.92,
                                opacity: 0,
                                ease: 'power1.in',
                                duration: 0.85
                            }, 0);
                        }
                        if (doctorsLayer) {
                            heroExitTl.to(doctorsLayer, {
                                yPercent: 10,
                                scale: 1.04,
                                opacity: 0.15,
                                ease: 'none',
                                duration: 1
                            }, 0);
                        }
                        const bottomUI = hero.querySelector('.hero-bottom-ui');
                        if (bottomUI) {
                            heroExitTl.to(bottomUI, {
                                y: -44,
                                opacity: 0,
                                ease: 'power1.out',
                                duration: 0.55
                            }, 0);
                        }
                    }

                    // ==========================================================
                    // 2. ENTRADA PREPARATÓRIA DO PALCO ANTES DE TRAVAR A PINAGEM
                    // Enquanto #scrolly-stage sobe até o topo, título e contorno da silhueta
                    // já se alinham perfeitamente no centro antes do pin começar.
                    // ==========================================================
                    const sobreHeading = document.getElementById('sobre-heading');
                    if (sobreHeading && !sobreHeading.dataset.splitDone) {
                        sobreHeading.dataset.splitDone = 'true';
                        const rawWords = sobreHeading.innerText.trim().split(/\s+/);
                        sobreHeading.innerHTML = rawWords.map(w => `<span class="word-mask"><span class="word-inner">${w}</span></span>`).join(' ');
                    }
                    const sobreWordInners = sobreHeading ? sobreHeading.querySelectorAll('.word-inner') : [];
                    const contourWrap = document.getElementById('scrolly-contour-wrap');

                    const entranceTl = gsap.timeline({
                        scrollTrigger: {
                            trigger: scrollyStage,
                            start: 'top 85%',
                            end: 'top top',
                            scrub: true,
                            invalidateOnRefresh: true
                        }
                    });

                    if (sobreWordInners.length) {
                        entranceTl.fromTo(sobreWordInners,
                            { yPercent: 105, rotateZ: 3, opacity: 0 },
                            { yPercent: 0, rotateZ: 0, opacity: 1, stagger: 0.03, ease: 'power3.out', duration: 0.9 },
                            0
                        );
                    }
                    if (contourWrap) {
                        entranceTl.fromTo(contourWrap,
                            { scale: 0.94, opacity: 0.2 },
                            { scale: 1, opacity: 1, ease: 'power2.out', duration: 0.9 },
                            0
                        );
                    }

                    // ==========================================================
                    // 3. PINAGEM DEDICADA EXCLUSIVAMENTE À ANIMAÇÃO DO MÉDICO + 4 PILARES
                    // 100% da distância pinada veste o jaleco e revela os 4 cards com precisão.
                    // ==========================================================
                    const coatTl = gsap.timeline({
                        scrollTrigger: {
                            trigger: scrollyStage,
                            start: 'top top',
                            end: () => '+=' + (window.innerWidth < 768 ? 360 : 560),
                            pin: true,
                            pinSpacing: true,
                            anticipatePin: 1,
                            scrub: window.__lenis ? true : 0.2,
                            invalidateOnRefresh: true,
                            onUpdate: (self) => {
                                if (scrollyProgressBar) {
                                    scrollyProgressBar.style.transform = `scaleX(${self.progress})`;
                                }
                                if (scrollyHud) {
                                    if (self.progress <= 0.01) {
                                        scrollyHud.style.opacity = '0';
                                        scrollyHud.style.pointerEvents = 'none';
                                    } else if (self.progress > 0.88) {
                                        const fade = Math.max(0, (1 - self.progress) / 0.12);
                                        scrollyHud.style.opacity = String(fade);
                                        scrollyHud.style.pointerEvents = 'none';
                                    } else {
                                        scrollyHud.style.opacity = '1';
                                        scrollyHud.style.pointerEvents = 'auto';
                                    }
                                }
                            },
                            onLeave: () => {
                                if (scrollyHud) {
                                    scrollyHud.style.opacity = '0';
                                    scrollyHud.style.pointerEvents = 'none';
                                }
                            },
                            onLeaveBack: () => {
                                if (scrollyHud) {
                                    scrollyHud.style.opacity = '0';
                                    scrollyHud.style.pointerEvents = 'none';
                                }
                            },
                            onEnterBack: () => {
                                if (scrollyHud) {
                                    scrollyHud.style.opacity = '1';
                                    scrollyHud.style.pointerEvents = 'auto';
                                }
                            }
                        }
                    });

                    // Veste o jaleco ao longo de praticamente toda a pinagem (0.00 -> 0.92)
                    coatTl.to(frameProxy, {
                        frame: TOTAL_FRAMES - 1,
                        ease: 'none',
                        duration: 0.92,
                        onUpdate: () => {
                            updateTargetFrame(frameProxy.frame);
                        }
                    }, 0);

                    // Os 4 cards informativos surgem em sequência fluida durante a vestimenta do jaleco
                    const card1 = document.getElementById('scrolly-card-1');
                    const card2 = document.getElementById('scrolly-card-2');
                    const card3 = document.getElementById('scrolly-card-3');
                    const card4 = document.getElementById('scrolly-card-4');

                    if (card1) {
                        coatTl.fromTo(card1,
                            { y: 24, scale: 0.94, opacity: 0 },
                            { y: 0, scale: 1, opacity: 1, ease: 'back.out(1.2)', duration: 0.18, onStart: () => card1.classList.add('scrolly-pillar-active'), onReverseComplete: () => card1.classList.remove('scrolly-pillar-active') },
                            0.08
                        );
                    }
                    if (card2) {
                        coatTl.fromTo(card2,
                            { y: 24, scale: 0.94, opacity: 0 },
                            { y: 0, scale: 1, opacity: 1, ease: 'back.out(1.2)', duration: 0.18, onStart: () => card2.classList.add('scrolly-pillar-active'), onReverseComplete: () => card2.classList.remove('scrolly-pillar-active') },
                            0.28
                        );
                    }
                    if (card3) {
                        coatTl.fromTo(card3,
                            { y: 24, scale: 0.94, opacity: 0 },
                            { y: 0, scale: 1, opacity: 1, ease: 'back.out(1.2)', duration: 0.18, onStart: () => card3.classList.add('scrolly-pillar-active'), onReverseComplete: () => card3.classList.remove('scrolly-pillar-active') },
                            0.48
                        );
                    }
                    if (card4) {
                        coatTl.fromTo(card4,
                            { y: 24, scale: 0.94, opacity: 0 },
                            { y: 0, scale: 1, opacity: 1, ease: 'back.out(1.2)', duration: 0.18, onStart: () => card4.classList.add('scrolly-pillar-active'), onReverseComplete: () => card4.classList.remove('scrolly-pillar-active') },
                            0.68
                        );
                    }

                    // Respiro final (0.92 -> 1.00) exibindo o médico completo antes de despinar para #vagas
                    coatTl.to({}, { duration: 0.08 }, 0.92);

                    window.addEventListener('load', () => {
                        if (typeof ScrollTrigger !== 'undefined') ScrollTrigger.refresh();
                    }, { once: true });
                }

});

// === js/specialties-carousel.js ===
document.addEventListener("DOMContentLoaded", () => {
        // 2. RENDERIZAR CARDS COM COR PREDOMINANTE & LOOP CIRCULAR INFINITO
        // -------------------------------------------------------------
        const specTrack = document.getElementById('spec-cards-track');
        let autoCycleTimer = null;
        let isAutoLooping = true;
        let isUserInteracting = false;
        let isTouchActive = false;
        let isCircularReady = false;
        let activeTargetLeft = null;
        let targetResetTimer = null;
        let resumeTimeout = null;
        let wrapTimer = null;

        const BUFFER_LEFT = 4;

        function getCardStep() {
            const firstCard = specTrack ? specTrack.querySelector('.spec-card') : null;
            if (!firstCard) return 320;
            const nextCard = firstCard.nextElementSibling;
            if (nextCard) {
                return nextCard.offsetLeft - firstCard.offsetLeft;
            }
            return firstCard.offsetWidth + 24;
        }

        function getTrackPaddingLeft() {
            if (!specTrack) return 0;
            return parseFloat(getComputedStyle(specTrack).paddingLeft) || 0;
        }

        // Lista circular real com apenas os 13 cards no DOM (sem clonar 3x)
        function rebalanceCircularTrack() {
            if (!isCircularReady || !specTrack || specTrack.children.length < 2) return;
            if (isTouchActive || specTrack.classList.contains('is-dragging')) return;

            const step = getCardStep();
            if (step <= 0) return;

            const padLeft = getTrackPaddingLeft();
            const minScroll = padLeft + (BUFFER_LEFT - 1) * step;
            const maxScroll = padLeft + (BUFFER_LEFT + 1) * step;

            if (specTrack.scrollLeft >= minScroll && specTrack.scrollLeft <= maxScroll) {
                return;
            }

            const prevSnap = specTrack.style.scrollSnapType;
            const prevBehavior = specTrack.style.scrollBehavior;
            specTrack.style.scrollSnapType = 'none';
            specTrack.style.scrollBehavior = 'auto';

            let guard = 0;
            while (specTrack.scrollLeft > maxScroll && guard < specialties.length) {
                const first = specTrack.firstElementChild;
                specTrack.appendChild(first);
                specTrack.scrollLeft -= step;
                if (activeTargetLeft !== null) activeTargetLeft -= step;
                guard++;
            }

            guard = 0;
            while (specTrack.scrollLeft < minScroll && guard < specialties.length) {
                const last = specTrack.lastElementChild;
                specTrack.insertBefore(last, specTrack.firstElementChild);
                specTrack.scrollLeft += step;
                if (activeTargetLeft !== null) activeTargetLeft += step;
                guard++;
            }

            // Garante commit de layout e scrollLeft antes de reativar scroll-snap
            void specTrack.offsetLeft;
            specTrack.style.scrollSnapType = prevSnap;
            specTrack.style.scrollBehavior = prevBehavior;
        }

        function stepCarousel(direction) {
            if (!specTrack || !isCircularReady) return;
            const step = getCardStep();
            const padLeft = getTrackPaddingLeft();

            if (activeTargetLeft === null) {
                rebalanceCircularTrack();
                const slot = Math.round((specTrack.scrollLeft - padLeft) / step);
                activeTargetLeft = padLeft + slot * step;
            }

            let nextLeft = activeTargetLeft + direction * step;
            const maxSafeLeft = specTrack.scrollWidth - specTrack.clientWidth - step * 0.5;
            if (nextLeft < padLeft + step || nextLeft > maxSafeLeft) {
                rebalanceCircularTrack();
                nextLeft = activeTargetLeft + direction * step;
            }

            activeTargetLeft = nextLeft;
            specTrack.scrollTo({ left: activeTargetLeft, behavior: 'smooth' });
            clearTimeout(targetResetTimer);
            targetResetTimer = setTimeout(() => {
                activeTargetLeft = null;
                rebalanceCircularTrack();
            }, 600);
        }

        function advanceCard() {
            stepCarousel(1);
        }

        function startAutoCycle() {
            if (autoCycleTimer) clearInterval(autoCycleTimer);
            autoCycleTimer = setInterval(() => {
                if (isAutoLooping && !isUserInteracting) {
                    advanceCard();
                }
            }, 3200);
        }

        function stopAutoCycle() {
            if (autoCycleTimer) clearInterval(autoCycleTimer);
            autoCycleTimer = null;
        }

        let specImagesHydrated = false;

        function hydrateSpecCardImages() {
            if (!specTrack || specImagesHydrated) return;
            specImagesHydrated = true;

            specTrack.querySelectorAll('img.spec-card-img').forEach((img) => {
                const targetSrc = img.getAttribute('data-src');
                if (targetSrc && !img.getAttribute('src')) {
                    img.setAttribute('src', targetSrc);
                }
                const markLoaded = () => img.classList.add('is-loaded');
                if (img.complete && img.naturalWidth > 0) {
                    markLoaded();
                } else {
                    img.addEventListener('load', markLoaded, { once: true });
                    img.addEventListener('error', markLoaded, { once: true });
                }
            });
        }

        function preloadSpecialtyImagesInBackground() {
            if (!window.__specPreloadStarted) {
                window.__specPreloadStarted = true;
                window.__preloadedSpecImages = window.__preloadedSpecImages || [];

                const uniqueUrls = [...new Set(specialties.map((s) => s.image))];
                uniqueUrls.forEach((url) => {
                    const preImg = new Image();
                    preImg.decoding = 'async';
                    if ('fetchPriority' in preImg) {
                        preImg.fetchPriority = 'low';
                    }
                    const markDomCards = () => {
                        if (!specTrack) return;
                        specTrack.querySelectorAll(`img.spec-card-img[data-src="${url}"]`).forEach((domImg) => {
                            if (!domImg.getAttribute('src')) {
                                domImg.setAttribute('src', url);
                            }
                            domImg.classList.add('is-loaded');
                        });
                    };
                    preImg.onload = () => {
                        if (typeof preImg.decode === 'function') {
                            preImg.decode().then(markDomCards).catch(markDomCards);
                        } else {
                            markDomCards();
                        }
                    };
                    preImg.onerror = markDomCards;
                    preImg.src = url;
                    window.__preloadedSpecImages.push(preImg);
                });
            }
            hydrateSpecCardImages();
        }

        function scheduleSpecialtyPreload() {
            const kick = () => {
                if ('requestIdleCallback' in window) {
                    requestIdleCallback(preloadSpecialtyImagesInBackground, { timeout: 350 });
                } else {
                    setTimeout(preloadSpecialtyImagesInBackground, 100);
                }
            };

            if (document.readyState === 'complete') {
                kick();
            } else {
                window.addEventListener('load', kick, { once: true });
            }

            // Garantia caso o usuário role rapidamente antes de window.load finalizar
            if ('IntersectionObserver' in window && specTrack) {
                const earlyObserver = new IntersectionObserver((entries) => {
                    if (entries.some((e) => e.isIntersecting)) {
                        earlyObserver.disconnect();
                        preloadSpecialtyImagesInBackground();
                    }
                }, { rootMargin: '1200px 0px' });
                earlyObserver.observe(specTrack);
            }
        }

        function rgbToCardNumColor(rgbStr) {
            const parts = (rgbStr || '').split(',').map((v) => Number(v.trim()) / 255);
            if (parts.length !== 3 || parts.some(Number.isNaN)) return '#34D399';
            const [r, g, b] = parts;
            const max = Math.max(r, g, b);
            const min = Math.min(r, g, b);
            const d = max - min;
            let h = 0;
            if (d !== 0) {
                if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) * 60;
                else if (max === g) h = ((b - r) / d + 2) * 60;
                else h = ((r - g) / d + 4) * 60;
            }
            const l = (max + min) / 2;
            const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
            const targetS = Math.round(Math.min(82, Math.max(58, s * 100)));
            return `hsl(${Math.round(h)}, ${targetS}%, 66%)`;
        }

        function buildSpecialtyCards() {
            if (!specTrack) return;

            // Apenas os 13 cards reais rotacionados em anel circular:
            // os últimos 4 ficam à esquerda do scroll inicial para permitir recuo imediato
            const total = specialties.length;
            const ringOrder = [];
            for (let offset = 0; offset < total; offset++) {
                ringOrder.push((total - BUFFER_LEFT + offset) % total);
            }

            specTrack.innerHTML = ringOrder.map((realIndex) => {
                const spec = specialties[realIndex];
                const numColor = rgbToCardNumColor(spec.rgb);
                return `
                    <article class="spec-card"
                             data-index="${realIndex}"
                             style="--card-rgb: ${spec.rgb}; --card-rgb-dark: ${spec.rgbDark}; --card-num-color: ${numColor};"
                             role="button"
                             tabindex="0"
                             aria-label="Ver detalhes de ${spec.title}">
                        <span class="spec-card-number">${realIndex + 1}</span>
                        <div class="spec-card-img-wrap">
                            <img data-src="${spec.image}"
                                 width="440"
                                 height="587"
                                 alt="${spec.title} - Faculdade de Medicina da UFF"
                                 class="spec-card-img"
                                 loading="eager"
                                 decoding="sync">
                        </div>
                        <div class="spec-card-gradient"></div>
                        <div class="spec-card-body">
                            <h3 class="spec-card-title">${spec.title}</h3>
                            <p class="spec-card-meta">${spec.vagasShort} • ${spec.duration} • ${spec.hours}</p>
                            <div class="spec-card-btn">
                                <span>Ver Detalhes</span>
                                <svg class="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M9 5l7 7-7 7"></path>
                                </svg>
                            </div>
                        </div>
                    </article>
                `;
            }).join('');

            scheduleSpecialtyPreload();

            // Posiciona no Card #1 (logo após o buffer esquerdo circular) antes de liberar o rebalanceamento
            const alignInitialTrack = () => {
                const step = getCardStep();
                const padLeft = getTrackPaddingLeft();
                const prevSnap = specTrack.style.scrollSnapType;
                const prevBehavior = specTrack.style.scrollBehavior;
                specTrack.style.scrollSnapType = 'none';
                specTrack.style.scrollBehavior = 'auto';
                specTrack.scrollLeft = padLeft + BUFFER_LEFT * step;
                void specTrack.offsetLeft;
                specTrack.style.scrollSnapType = prevSnap;
                specTrack.style.scrollBehavior = prevBehavior;
            };
            alignInitialTrack();
            requestAnimationFrame(() => {
                alignInitialTrack();
                requestAnimationFrame(() => {
                    clearTimeout(wrapTimer);
                    isCircularReady = true;
                });
            });

            // Click & keyboard handler to open specialty modal
            let dragMoved = false;
            specTrack.querySelectorAll('.spec-card').forEach((card) => {
                card.addEventListener('click', () => {
                    if (dragMoved) return;
                    const idx = Number(card.getAttribute('data-index'));
                    openSpecialtyModal(specialties[idx]);
                });
                card.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        const idx = Number(card.getAttribute('data-index'));
                        openSpecialtyModal(specialties[idx]);
                    }
                });
            });

            // Prev / Next navigation buttons
            const prevBtn = document.getElementById('spec-prev');
            const nextBtn = document.getElementById('spec-next');
            if (prevBtn) {
                prevBtn.addEventListener('click', () => {
                    isUserInteracting = true;
                    stepCarousel(-1);
                    clearTimeout(resumeTimeout);
                    resumeTimeout = setTimeout(() => { isUserInteracting = false; }, 3500);
                });
            }
            if (nextBtn) {
                nextBtn.addEventListener('click', () => {
                    isUserInteracting = true;
                    stepCarousel(1);
                    clearTimeout(resumeTimeout);
                    resumeTimeout = setTimeout(() => { isUserInteracting = false; }, 3500);
                });
            }

            // Loop Toggle button
            const loopToggleBtn = document.getElementById('spec-loop-toggle');
            const loopIndicator = document.getElementById('loop-indicator');
            const loopLabel = document.getElementById('loop-label');
            if (loopToggleBtn) {
                loopToggleBtn.addEventListener('click', () => {
                    isAutoLooping = !isAutoLooping;
                    if (isAutoLooping) {
                        loopIndicator.classList.remove('bg-slate-500');
                        loopIndicator.classList.add('bg-brand-emerald', 'animate-pulse');
                        loopLabel.textContent = 'Auto-Loop';
                        startAutoCycle();
                    } else {
                        loopIndicator.classList.remove('bg-brand-emerald', 'animate-pulse');
                        loopIndicator.classList.add('bg-slate-500');
                        loopLabel.textContent = 'Pausado';
                        stopAutoCycle();
                    }
                });
            }

            function scheduleRebalance(delay = 140) {
                clearTimeout(wrapTimer);
                wrapTimer = setTimeout(() => {
                    if (!isTouchActive && !specTrack.classList.contains('is-dragging') && activeTargetLeft === null) {
                        rebalanceCircularTrack();
                    }
                }, delay);
            }

            // Mouse hover / touch pause
            specTrack.addEventListener('mouseenter', () => { isUserInteracting = true; });
            specTrack.addEventListener('mouseleave', () => { isUserInteracting = false; });
            specTrack.addEventListener('wheel', () => {
                activeTargetLeft = null;
                clearTimeout(targetResetTimer);
            }, { passive: true });
            specTrack.addEventListener('touchstart', () => {
                isTouchActive = true;
                isUserInteracting = true;
                activeTargetLeft = null;
                clearTimeout(targetResetTimer);
                clearTimeout(wrapTimer);
            }, { passive: true });
            const handleTouchRelease = () => {
                isTouchActive = false;
                scheduleRebalance(140);
                clearTimeout(resumeTimeout);
                resumeTimeout = setTimeout(() => { isUserInteracting = false; }, 2800);
            };
            specTrack.addEventListener('touchend', handleTouchRelease, { passive: true });
            specTrack.addEventListener('touchcancel', handleTouchRelease, { passive: true });

            // Reequilibra o anel circular quando o scroll assenta
            specTrack.addEventListener('scroll', () => {
                if (!isCircularReady) return;
                if (!isTouchActive && !specTrack.classList.contains('is-dragging')) {
                    scheduleRebalance(140);
                }
            }, { passive: true });
            if ('onscrollend' in window) {
                specTrack.addEventListener('scrollend', () => {
                    if (!isCircularReady) return;
                    if (!isTouchActive && !specTrack.classList.contains('is-dragging')) {
                        activeTargetLeft = null;
                        clearTimeout(targetResetTimer);
                        rebalanceCircularTrack();
                    }
                }, { passive: true });
            }

            let resizeTimer = null;
            window.addEventListener('resize', () => {
                clearTimeout(resizeTimer);
                resizeTimer = setTimeout(() => {
                    activeTargetLeft = null;
                    rebalanceCircularTrack();
                }, 150);
            }, { passive: true });

            // Mouse drag-to-scroll for desktop
            let isDown = false;
            let startX = 0;
            let scrollLeft = 0;
            specTrack.addEventListener('mousedown', (e) => {
                isDown = true;
                dragMoved = false;
                isUserInteracting = true;
                activeTargetLeft = null;
                clearTimeout(targetResetTimer);
                clearTimeout(wrapTimer);
                specTrack.classList.add('is-dragging');
                startX = e.pageX - specTrack.offsetLeft;
                scrollLeft = specTrack.scrollLeft;
            });
            window.addEventListener('mouseup', () => {
                if (!isDown) return;
                isDown = false;
                specTrack.classList.remove('is-dragging');
                scheduleRebalance(80);
                clearTimeout(resumeTimeout);
                resumeTimeout = setTimeout(() => { isUserInteracting = false; }, 2500);
                setTimeout(() => { dragMoved = false; }, 50);
            });
            specTrack.addEventListener('mousemove', (e) => {
                if (!isDown) return;
                const x = e.pageX - specTrack.offsetLeft;
                const walk = (x - startX) * 1.3;
                if (Math.abs(walk) > 8) {
                    dragMoved = true;
                    e.preventDefault();
                    specTrack.scrollLeft = scrollLeft - walk;
                }
            });

            startAutoCycle();
        }

        // -------------------------------------------------------------
        // 2.1 RODA ORBITAL DE DISCIPLINAS (OPTION WHEEL + SELO FACMED UFF)
        // -------------------------------------------------------------
        function initDisciplinesOptionWheel() {
            const sectionEl = document.getElementById('disciplinas-section');
            const viewportEl = document.getElementById('credits-viewport');
            const wheelEl = document.getElementById('disciplines-wheel');
            const srListEl = document.getElementById('spec-accessible-list');

            if (!wheelEl || !viewportEl || !specialties.length) return;

            const n = specialties.length;
            const SMOOTHING_MS = 410;
            const CURVE = 1;
            const BLUR_STEP = 2;
            const FADE_STEP = 0.25;
            const MIN_OPACITY = 0.05;
            const AUTO_STEP_MS = 2300;

            const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            const modIdx = (idx) => ((idx % n) + n) % n;
            const lerp = (a, b, t) => a + (b - a) * t;

            // Popula itens da roda orbital
            wheelEl.innerHTML = specialties.map((spec, idx) => `
                <div id="wheel-opt-${idx}"
                     class="option-wheel__item${idx === 0 ? ' option-wheel__item--selected' : ''}"
                     role="option"
                     data-index="${idx}"
                     aria-selected="${idx === 0 ? 'true' : 'false'}">
                    ${spec.title}
                </div>
            `).join('');

            const itemEls = Array.from(wheelEl.querySelectorAll('.option-wheel__item'));
            wheelEl.setAttribute('aria-activedescendant', 'wheel-opt-0');

            // Lista semântica acessível para leitores de tela
            if (srListEl) {
                srListEl.innerHTML = specialties.map((spec, index) => `
                    <li>
                        <strong>${index + 1}. ${spec.title}</strong>: ${spec.vagasShort}. Duração: ${spec.duration} (${spec.hours}). Início: ${spec.inicio}. Pré-requisito: ${spec.prereq}.
                    </li>
                `).join('');
            }

            let cfg = {
                fontSize: 2.8,
                spacing: 1.05,
                tilt: 7.4,
                cx: -26,
                inset: 338,
                rowH: 47.04,
                tiltRad: (7.4 * Math.PI) / 180,
                R: 364.2,
                emblemSize: 530
            };

            function updateGeometry() {
                const remPx = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
                const width = viewportEl.clientWidth || window.innerWidth;

                let fontSize;
                let spacing;
                let tilt;
                let cx;
                let emblemSize;

                if (width >= 1360) {
                    fontSize = 2.8;
                    spacing = 1.05;
                    tilt = 7.4;
                    cx = -26;
                } else if (width >= 1024) {
                    const t = (width - 1024) / (1360 - 1024);
                    fontSize = lerp(1.9, 2.55, t);
                    spacing = lerp(1.08, 1.05, t);
                    tilt = lerp(8.0, 7.4, t);
                    cx = lerp(-24, -26, t);
                } else if (width >= 640) {
                    const t = (width - 640) / (1024 - 640);
                    fontSize = lerp(1.5, 1.85, t);
                    spacing = lerp(1.22, 1.12, t);
                    tilt = lerp(8.8, 8.2, t);
                    cx = lerp(-22, -24, t);
                } else {
                    fontSize = width < 380 ? 1.1 : 1.18;
                    spacing = 1.44;
                    tilt = 9.6;
                    cx = -22;
                }

                const rowH = fontSize * remPx * spacing;
                const tiltRad = (tilt * Math.PI) / 180;
                const R = rowH / tiltRad;

                if (width >= 1024) {
                    const idealCx = width * 0.34 - 300;
                    const maxSafeCx = width - R - 760;
                    cx = Math.round(Math.max(-24, Math.min(idealCx, maxSafeCx)));
                }

                const inset = Math.round(cx + R);

                if (width >= 1360) {
                    emblemSize = 530;
                } else if (width >= 1024) {
                    emblemSize = Math.round(Math.min(510, Math.max(340, R * 1.44)));
                } else if (width >= 640) {
                    emblemSize = Math.round(Math.min(410, Math.max(270, R * 1.4)));
                } else {
                    emblemSize = Math.round(Math.min(228, Math.max(185, R * 1.36)));
                }

                cfg = { fontSize, spacing, tilt, cx, inset, rowH, tiltRad, R, emblemSize };

                viewportEl.style.setProperty('--ow-font-size', `${fontSize.toFixed(3)}rem`);
                viewportEl.style.setProperty('--ow-inset', `${inset}px`);
                viewportEl.style.setProperty('--ow-cx', `${cx.toFixed(1)}px`);
                viewportEl.style.setProperty('--ow-emblem-size', `${emblemSize}px`);
            }

            let pos = 0;
            let target = 0;
            let selectedIdx = 0;
            let rafId = null;
            let lastTime = 0;
            let isInView = true;
            let isHovering = false;
            let isDragging = false;
            let dragStartY = 0;
            let dragStartTarget = 0;
            let dragMoved = false;
            let pauseAutoUntil = 0;

            const isModalOpen = () => modal && !modal.classList.contains('pointer-events-none');

            function syncSelection(nextIdx) {
                if (nextIdx === selectedIdx) return;
                const prevEl = itemEls[selectedIdx];
                const nextEl = itemEls[nextIdx];
                if (prevEl) {
                    prevEl.classList.remove('option-wheel__item--selected');
                    prevEl.setAttribute('aria-selected', 'false');
                }
                if (nextEl) {
                    nextEl.classList.add('option-wheel__item--selected');
                    nextEl.setAttribute('aria-selected', 'true');
                    wheelEl.setAttribute('aria-activedescendant', nextEl.id);
                }
                selectedIdx = nextIdx;
            }

            function paint(value) {
                const { tiltRad, R } = cfg;
                const wrapped = ((value % n) + n) % n;

                for (let i = 0; i < n; i++) {
                    const el = itemEls[i];
                    if (!el) continue;

                    let d = i - wrapped;
                    if (d > n / 2) d -= n;
                    else if (d < -n / 2) d += n;

                    const absD = Math.abs(d);
                    const steps = absD;
                    let opacity = Math.max(MIN_OPACITY, 1 - steps * FADE_STEP);
                    if (absD > 5.4) {
                        opacity *= Math.max(0, 1 - (absD - 5.4) / 0.9);
                    }

                    if (opacity <= 0.004 || absD > 6.35) {
                        el.style.visibility = 'hidden';
                        el.style.opacity = '0';
                        continue;
                    }

                    const ang = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, d * tiltRad));
                    const y = R * Math.sin(ang);
                    const x = -R * (1 - Math.cos(ang)) * CURVE;
                    const rot = (ang * 180) / Math.PI;
                    const p = Math.max(0, Math.min(1, 1 - steps));
                    const blurPx = prefersReducedMotion ? 0 : (steps < 0.02 ? 0 : steps * BLUR_STEP);

                    el.style.visibility = 'visible';
                    el.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0) translateY(-50%) rotate(${rot.toFixed(2)}deg)`;
                    el.style.opacity = opacity.toFixed(3);
                    el.style.filter = blurPx > 0.05 ? `blur(${blurPx.toFixed(2)}px)` : 'none';
                    el.style.setProperty('--ow-p', p.toFixed(3));
                    el.style.zIndex = String(Math.round(50 - steps * 4));
                }

                syncSelection(modIdx(Math.round(value)));
            }

            function stepFrame(now) {
                if (!lastTime) lastTime = now;
                const dt = Math.min(0.05, Math.max(0.001, (now - lastTime) / 1000));
                lastTime = now;

                const diff = target - pos;
                if (prefersReducedMotion || Math.abs(diff) < 0.0008) {
                    pos = target;
                    paint(pos);
                    rafId = null;
                    lastTime = 0;
                    return;
                }

                const tau = SMOOTHING_MS / 1000;
                const k = isDragging ? Math.min(1, dt * 18) : (1 - Math.exp(-dt / tau));
                pos += diff * k;
                paint(pos);

                if (isInView && !document.hidden) {
                    rafId = requestAnimationFrame(stepFrame);
                } else {
                    rafId = null;
                    lastTime = 0;
                }
            }

            function ensureLoop() {
                if (prefersReducedMotion) {
                    pos = target;
                    paint(pos);
                    return;
                }
                if (!rafId && isInView && !document.hidden) {
                    lastTime = 0;
                    rafId = requestAnimationFrame(stepFrame);
                }
            }

            function goToShortestIndex(itemIdx, openIfCentered) {
                const curIdx = modIdx(Math.round(target));
                let diff = itemIdx - curIdx;
                if (diff > n / 2) diff -= n;
                else if (diff < -n / 2) diff += n;

                if (diff === 0 && openIfCentered) {
                    pauseAutoUntil = Date.now() + 4500;
                    openSpecialtyModal(specialties[itemIdx]);
                    return;
                }

                target = Math.round(target) + diff;
                pauseAutoUntil = Date.now() + 4500;
                ensureLoop();
            }

            // Cliques diretos nas opções da roda
            wheelEl.addEventListener('click', (e) => {
                if (dragMoved) {
                    dragMoved = false;
                    return;
                }
                const item = e.target.closest('.option-wheel__item');
                if (!item) return;
                const idx = Number(item.getAttribute('data-index'));
                if (Number.isNaN(idx)) return;
                goToShortestIndex(idx, true);
            });

            // Arraste vertical direto com mouse/caneta (mantém scroll vertical nativo da página no toque mobile)
            wheelEl.addEventListener('pointerdown', (e) => {
                if (e.pointerType === 'touch') return;
                if (e.button && e.button !== 0) return;
                isDragging = true;
                dragMoved = false;
                dragStartY = e.clientY;
                dragStartTarget = target;
                pauseAutoUntil = Date.now() + 5000;
                wheelEl.classList.add('option-wheel--dragging');
                try { wheelEl.setPointerCapture(e.pointerId); } catch (_) {}
                ensureLoop();
            });

            wheelEl.addEventListener('pointermove', (e) => {
                if (!isDragging) return;
                const dy = e.clientY - dragStartY;
                if (Math.abs(dy) > 5) dragMoved = true;
                target = dragStartTarget - dy / Math.max(20, cfg.rowH);
                pauseAutoUntil = Date.now() + 5000;
                ensureLoop();
            });

            const finishDrag = (e) => {
                if (!isDragging) return;
                isDragging = false;
                wheelEl.classList.remove('option-wheel--dragging');
                try { wheelEl.releasePointerCapture(e.pointerId); } catch (_) {}
                target = Math.round(target);
                pauseAutoUntil = Date.now() + 3800;
                ensureLoop();
                setTimeout(() => { dragMoved = false; }, 40);
            };
            wheelEl.addEventListener('pointerup', finishDrag);
            wheelEl.addEventListener('pointercancel', finishDrag);

            // Teclado acessível (Setas / Enter)
            wheelEl.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
                    e.preventDefault();
                    target = Math.round(target) + 1;
                    pauseAutoUntil = Date.now() + 4500;
                    ensureLoop();
                } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
                    e.preventDefault();
                    target = Math.round(target) - 1;
                    pauseAutoUntil = Date.now() + 4500;
                    ensureLoop();
                } else if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    openSpecialtyModal(specialties[selectedIdx]);
                }
            });

            // Pausa elegante durante hover na área de interação
            if (sectionEl) {
                sectionEl.addEventListener('mouseenter', () => { isHovering = true; });
                sectionEl.addEventListener('mouseleave', () => { isHovering = false; });
            }

            // Giro orbital cinematográfico ao chegar na seção e resposta suave ao scroll da página
            let hasPlayedEntrance = false;
            let lastScrollY = window.scrollY;
            let scrollSnapTimer = null;

            const triggerEntranceSpin = () => {
                if (hasPlayedEntrance || prefersReducedMotion) return;
                hasPlayedEntrance = true;
                pos = target - 3.6;
                paint(pos);
                pauseAutoUntil = Date.now() + 2600;
                ensureLoop();
            };

            window.addEventListener('scroll', () => {
                const currentScrollY = window.scrollY;
                const deltaY = currentScrollY - lastScrollY;
                lastScrollY = currentScrollY;

                if (!isInView || prefersReducedMotion || isDragging || isModalOpen()) return;
                if (!hasPlayedEntrance) {
                    const rect = (sectionEl || viewportEl).getBoundingClientRect();
                    if (rect.top < window.innerHeight * 0.88 && rect.bottom > 0) {
                        triggerEntranceSpin();
                        return;
                    }
                }
                if (Math.abs(deltaY) < 1) return;

                target += deltaY * 0.0055;
                pauseAutoUntil = Date.now() + 2600;
                ensureLoop();

                clearTimeout(scrollSnapTimer);
                scrollSnapTimer = setTimeout(() => {
                    if (!isDragging) {
                        target = Math.round(target);
                        ensureLoop();
                    }
                }, 150);
            }, { passive: true });

            // Auto-rotação orbital suave para cima quando visível
            let autoTimer = null;
            if (!prefersReducedMotion) {
                autoTimer = setInterval(() => {
                    if (!isInView || document.hidden || isHovering || isDragging || isModalOpen()) return;
                    if (Date.now() < pauseAutoUntil) return;
                    target = Math.round(target) + 1;
                    ensureLoop();
                }, AUTO_STEP_MS);
            }

            // Pausar rAF quando a seção estiver fora da tela e disparar giro na chegada
            if ('IntersectionObserver' in window) {
                const viewObserver = new IntersectionObserver((entries) => {
                    isInView = entries.some((entry) => entry.isIntersecting);
                    if (isInView) {
                        const rect = (sectionEl || viewportEl).getBoundingClientRect();
                        if (!hasPlayedEntrance && rect.top < window.innerHeight * 0.9 && rect.bottom > 0) {
                            triggerEntranceSpin();
                        } else {
                            paint(pos);
                            if (Math.abs(target - pos) > 0.001) ensureLoop();
                        }
                    } else {
                        hasPlayedEntrance = false;
                        if (rafId) {
                            cancelAnimationFrame(rafId);
                            rafId = null;
                        }
                    }
                }, { rootMargin: '0px' });
                viewObserver.observe(sectionEl || viewportEl);
            }

            document.addEventListener('visibilitychange', () => {
                if (!document.hidden && isInView && Math.abs(target - pos) > 0.001) {
                    ensureLoop();
                }
            });

            // Recalculo geométrico responsivo (ResizeObserver + window resize)
            const handleResize = () => {
                updateGeometry();
                paint(pos);
            };
            if ('ResizeObserver' in window) {
                const ro = new ResizeObserver(handleResize);
                ro.observe(viewportEl);
            } else {
                window.addEventListener('resize', handleResize, { passive: true });
            }

            updateGeometry();
            paint(pos);
        }

        buildSpecialtyCards();
        initDisciplinesOptionWheel();

        // -------------------------------------------------------------
        // 3. MODAL DE DETALHES DA ESPECIALIDADE (COM DADOS DO EDITAL)
        // -------------------------------------------------------------
        const modal = document.getElementById('specialty-modal');
        const modalContent = document.getElementById('modal-content');
        const modalClose = document.getElementById('modal-close');

        function openSpecialtyModal(spec) {
            isUserInteracting = true;
            modalContent.innerHTML = `
                <div class="flex flex-wrap items-center justify-between gap-2 text-xs font-mono pb-2 mb-2 pr-8">
                    <span class="text-brand-gold font-bold uppercase tracking-wider text-[11px]">
                        Previsão 2027 • Base Edital CMM Nº 1 (UFF)
                    </span>
                    <span class="text-brand-gold font-bold text-xs bg-brand-gold/15 px-3 py-1 rounded-full">
                        ${spec.vagas}
                    </span>
                </div>

                <h2 class="font-black text-2xl sm:text-3xl text-white mt-1">${spec.fullTitle || spec.title}</h2>
                <div class="text-xs font-mono text-slate-300 mt-1 uppercase tracking-wider">Início Previsto: <strong class="text-white">${spec.inicio}</strong> • Mínimo: <strong class="text-white">${spec.minAlunos}</strong></div>
                
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-5 text-xs sm:text-sm">
                    <div class="glass-card p-3.5 rounded-xl">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">Duração Oficial</span>
                        <strong class="text-white text-sm sm:text-base font-bold">${spec.duration}</strong>
                    </div>
                    <div class="glass-card p-3.5 rounded-xl">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">Carga Horária Total</span>
                        <strong class="text-white text-sm sm:text-base font-bold">${spec.hours}</strong>
                    </div>
                    <div class="glass-card p-3.5 rounded-xl">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">1ª Etapa (Prova Escrita)</span>
                        <strong class="text-slate-100 font-semibold text-xs sm:text-sm leading-relaxed block mt-1">${spec.stage1}</strong>
                    </div>
                    <div class="glass-card p-3.5 rounded-xl">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">2ª Etapa (Classificatória)</span>
                        <strong class="text-slate-100 font-semibold text-xs sm:text-sm leading-relaxed block mt-1">${spec.stage2}</strong>
                    </div>
                    <div class="glass-card p-3.5 rounded-xl sm:col-span-2">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">Pré-Requisito (Item 1.1 do Edital)</span>
                        <strong class="text-slate-200 font-medium text-xs sm:text-sm leading-relaxed block mt-1">${spec.prereq}</strong>
                    </div>
                    <div class="glass-card p-3.5 rounded-xl sm:col-span-2">
                        <span class="text-slate-400 block text-[11px] uppercase font-mono">Diploma Obtido no Exterior</span>
                        <strong class="text-slate-200 font-medium text-xs sm:text-sm leading-relaxed block mt-1">${spec.revalidacao}</strong>
                    </div>
                </div>

                <div class="flex flex-col sm:flex-row items-center gap-3 pt-2">
                    <a href="https://editais.uff.br/sites/default/files/arquivos/Edital%20Unificado.pdf" target="_blank" rel="noopener noreferrer" class="w-full sm:w-auto px-5 py-2.5 rounded-full text-xs font-bold text-white bg-brand-emerald hover:bg-emerald-500 text-center transition-all shadow-glow-emerald">
                        Consultar Edital Oficial (PDF)
                    </a>
                    <a href="mailto:concursos.cmm@id.uff.br" class="w-full sm:w-auto px-5 py-2.5 rounded-full text-xs font-semibold text-slate-300 hover:text-white glass-pill text-center transition-all">
                        Contato Edital: concursos.cmm@id.uff.br
                    </a>
                </div>
            `;
            modal.classList.remove('opacity-0', 'pointer-events-none');
        }

        modalClose.onclick = () => {
            modal.classList.add('opacity-0', 'pointer-events-none');
            setTimeout(() => { isUserInteracting = false; }, 1500);
        };
        modal.onclick = (e) => {
            if (e.target === modal) {
                modal.classList.add('opacity-0', 'pointer-events-none');
                setTimeout(() => { isUserInteracting = false; }, 1500);
            }
        };

        // -------------------------------------------------------------
});

// === js/kinetic-typography.js ===
/**
 * UFF Medicina 2027 - Tipografia Cinética e Revelações no Scroll
 * Curtain Rise nos títulos, leitura iluminada nos parágrafos e micro-interações
 */
document.addEventListener('DOMContentLoaded', () => {
    if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return;

            // Image reveals in lower sections
            gsap.utils.toArray('.img-reveal-wrap').forEach((wrap) => {
                const img = wrap.querySelector('img');
                if (img) {
                    gsap.fromTo(img, 
                        { scale: 1.15, y: -15 }, 
                        {
                            scale: 1,
                            y: 15,
                            scrollTrigger: {
                                trigger: wrap,
                                start: 'top bottom',
                                end: 'bottom top',
                                scrub: true
                            }
                        }
                    );
                }
            });


            // 10. KINETIC TYPOGRAPHY & SCROLL-INTERACTIVE CHOREOGRAPHY
            //     (INSPIRADO EM THE ROMANS — AUTÊNTICO & FLUIDO)
            // -------------------------------------------------------------
            const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            if (!reduceMotion) {

                // Helper: Divide títulos em máscaras de palavras para revelação editorial (Curtain Rise)
                const splitHeadingWords = (el) => {
                    if (!el || el.dataset.splitDone) return [];
                    el.dataset.splitDone = 'true';
                    const words = el.innerText.trim().split(/\s+/);
                    el.innerHTML = words.map(w => `<span class="word-mask"><span class="word-inner">${w}</span></span>`).join(' ');
                    return el.querySelectorAll('.word-inner');
                };

                // Helper: Divide parágrafos em palavras que acendem progressivamente com o scroll (Scrub Reading)
                const splitParagraphLitWords = (el) => {
                    if (!el || el.dataset.litDone) return [];
                    el.dataset.litDone = 'true';
                    const words = el.innerText.trim().split(/\s+/);
                    el.innerHTML = words.map(w => `<span class="scroll-lit-word" style="opacity: 0.25;">${w}</span>`).join(' ');
                    return el.querySelectorAll('.scroll-lit-word');
                };

                // 10.1. Títulos de todas as seções no <main>: Subida cinética das palavras + reação elástica ao scroll
                const sectionHeadings = document.querySelectorAll('#main-content h2, #disciplinas-section h3');
                sectionHeadings.forEach((heading) => {
                    const wordInners = splitHeadingWords(heading);
                    if (!wordInners.length) return;

                    gsap.fromTo(wordInners,
                        { yPercent: 120, rotateZ: 5, opacity: 0 },
                        {
                            yPercent: 0,
                            rotateZ: 0,
                            opacity: 1,
                            stagger: 0.045,
                            duration: 0.85,
                            ease: 'power3.out',
                            scrollTrigger: {
                                trigger: heading,
                                start: 'top 88%',
                                end: 'top 55%',
                                toggleActions: 'play none none reverse'
                            }
                        }
                    );
                });

                // 10.2. Subtítulos editoriais com iluminação progressiva palavra por palavra controlada pelo Scroll (Scrub)
                const scrubSubtitles = document.querySelectorAll(
                    '#especialidades > div:first-child p, #cronograma > div:first-child p, #selecao > div:first-child p, #main-content > section:last-of-type p'
                );
                scrubSubtitles.forEach((p) => {
                    const litWords = splitParagraphLitWords(p);
                    if (!litWords.length) return;

                    gsap.fromTo(litWords,
                        { opacity: 0.22, y: 6 },
                        {
                            opacity: 1,
                            y: 0,
                            stagger: 0.05,
                            ease: 'none',
                            scrollTrigger: {
                                trigger: p,
                                start: 'top 88%',
                                end: 'top 52%',
                                scrub: 0.4
                            }
                        }
                    );
                });

                // 10.3. Cards de Indicadores (#vagas): Entrada 3D com inclinação e surgimento escalonado
                const statCards = gsap.utils.toArray('#vagas .stat-card');
                if (statCards.length) {
                    gsap.fromTo(statCards,
                        { y: 65, opacity: 0, scale: 0.92, rotateX: 12 },
                        {
                            y: 0,
                            opacity: 1,
                            scale: 1,
                            rotateX: 0,
                            stagger: 0.14,
                            duration: 0.9,
                            ease: 'power3.out',
                            scrollTrigger: {
                                trigger: '#vagas',
                                start: 'top 86%',
                                toggleActions: 'play none none reverse'
                            }
                        }
                    );
                }

                // 10.4. Seção Especialidades: Controles de navegação, Carrossel de Cards e Créditos surgindo em cascata
                const specControls = document.querySelector('#especialidades > div:first-child > div:last-child');
                if (specControls) {
                    gsap.fromTo(specControls,
                        { x: 35, opacity: 0 },
                        {
                            x: 0,
                            opacity: 1,
                            duration: 0.8,
                            ease: 'power3.out',
                            scrollTrigger: {
                                trigger: '#especialidades',
                                start: 'top 82%',
                                toggleActions: 'play none none reverse'
                            }
                        }
                    );
                }

                const specTrackWrap = document.getElementById('spec-cards-track');
                if (specTrackWrap) {
                    gsap.fromTo(specTrackWrap,
                        { y: 24, opacity: 1 },
                        {
                            y: 0,
                            opacity: 1,
                            duration: 0.65,
                            ease: 'power2.out',
                            scrollTrigger: {
                                trigger: specTrackWrap,
                                start: 'top 92%',
                                once: true
                            }
                        }
                    );
                }

                const creditsViewport = document.getElementById('credits-viewport');
                if (creditsViewport) {
                    const wheelEmblemImg = creditsViewport.querySelector('.wheel-emblem-img');
                    const wheelEl = document.getElementById('disciplines-wheel');

                    const wheelTl = gsap.timeline({
                        scrollTrigger: {
                            trigger: '#disciplinas-section',
                            start: 'top 86%',
                            end: 'top 52%',
                            toggleActions: 'play none none reverse'
                        }
                    });

                    if (wheelEmblemImg) {
                        wheelTl.fromTo(wheelEmblemImg,
                            { x: -72, scale: 0.86, opacity: 0 },
                            {
                                x: 0,
                                scale: 1,
                                opacity: 0.8,
                                duration: 0.9,
                                ease: 'power3.out'
                            },
                            0
                        );

                        gsap.fromTo(wheelEmblemImg,
                            { rotation: -8 },
                            {
                                rotation: 8,
                                ease: 'none',
                                scrollTrigger: {
                                    trigger: '#disciplinas-section',
                                    start: 'top bottom',
                                    end: 'bottom top',
                                    scrub: 0.5
                                }
                            }
                        );
                    }

                    if (wheelEl) {
                        wheelTl.fromTo(wheelEl,
                            { x: 42, y: 36, scale: 0.95, opacity: 0 },
                            {
                                x: 0,
                                y: 0,
                                scale: 1,
                                opacity: 1,
                                duration: 0.85,
                                ease: 'power3.out'
                            },
                            0.08
                        );
                    }
                }

                // 10.5. Seção Cronograma: Painel HUD de Contagem Regressiva + Linha do Tempo desenhada pelo Scroll
                const hudPanel = document.querySelector('#cronograma .glass-card');
                if (hudPanel) {
                    gsap.fromTo(hudPanel,
                        { y: 55, opacity: 0, scale: 0.96 },
                        {
                            y: 0,
                            opacity: 1,
                            scale: 1,
                            duration: 0.9,
                            ease: 'power3.out',
                            scrollTrigger: {
                                trigger: hudPanel,
                                start: 'top 86%',
                                toggleActions: 'play none none reverse'
                            }
                        }
                    );

                    const hudDigits = hudPanel.querySelectorAll('.grid-cols-4 > div');
                    if (hudDigits.length) {
                        gsap.fromTo(hudDigits,
                            { y: 30, opacity: 0, scale: 0.88 },
                            {
                                y: 0,
                                opacity: 1,
                                scale: 1,
                                stagger: 0.09,
                                duration: 0.7,
                                ease: 'back.out(1.5)',
                                scrollTrigger: {
                                    trigger: hudPanel,
                                    start: 'top 80%',
                                    toggleActions: 'play none none reverse'
                                }
                            }
                        );
                    }
                }

                // Animação dos passos do Cronograma conforme o scroll
                const timelineContainer = document.querySelector('#cronograma .border-l-2');
                if (timelineContainer) {
                    const timelineSteps = timelineContainer.querySelectorAll('.group');
                    timelineSteps.forEach((step, idx) => {
                        const dot = step.querySelector('.timeline-dot') || step.querySelector('div:first-child');
                        const dateTag = step.querySelector('.step-date-tag') || step.querySelector('span');
                        const stepTitle = step.querySelector('h4');
                        const stepDesc = step.querySelector('p');
                        const highlightCard = step.querySelector('.timeline-highlight-card');

                        const stepTl = gsap.timeline({
                            scrollTrigger: {
                                trigger: step,
                                start: 'top 86%',
                                end: 'top 55%',
                                toggleActions: 'play none none reverse'
                            }
                        });

                        if (dot) {
                            stepTl.fromTo(dot,
                                { scale: 0, opacity: 0 },
                                { scale: 1, opacity: 1, duration: 0.4, ease: 'back.out(2)' },
                                0
                            );
                        }
                        if (highlightCard) {
                            stepTl.fromTo(highlightCard,
                                { y: 28, opacity: 0, scale: 0.98 },
                                { y: 0, opacity: 1, scale: 1, duration: 0.65, ease: 'power3.out' },
                                0.04
                            );
                        }
                        if (dateTag) {
                            stepTl.fromTo(dateTag,
                                { x: -20, opacity: 0 },
                                { x: 0, opacity: 1, duration: 0.45, ease: 'power2.out' },
                                0.08
                            );
                        }
                        if (stepTitle) {
                            stepTl.fromTo(stepTitle,
                                { x: 25, opacity: 0 },
                                { x: 0, opacity: 1, duration: 0.55, ease: 'power3.out' },
                                0.12
                            );
                        }
                        if (stepDesc) {
                            stepTl.fromTo(stepDesc,
                                { y: 15, opacity: 0 },
                                { y: 0, opacity: 1, duration: 0.5, ease: 'power2.out' },
                                0.18
                            );
                        }
                    });
                }

                // 10.6. Seção Seleção (#selecao): Cards de Fase 1 e Fase 2 surgindo em convergência 3D com textos animados
                const selecaoCards = gsap.utils.toArray('#selecao .glass-card');
                selecaoCards.forEach((card, i) => {
                    const fromX = i === 0 ? -45 : 45;
                    const rotZ = i === 0 ? -1.5 : 1.5;

                    gsap.fromTo(card,
                        { x: fromX, y: 50, rotateZ: rotZ, opacity: 0, scale: 0.95 },
                        {
                            x: 0,
                            y: 0,
                            rotateZ: 0,
                            opacity: 1,
                            scale: 1,
                            duration: 0.9,
                            ease: 'power3.out',
                            scrollTrigger: {
                                trigger: card,
                                start: 'top 86%',
                                toggleActions: 'play none none reverse'
                            }
                        }
                    );

                    const cardTitle = card.querySelector('h3');
                    const cardDesc = card.querySelector('p');
                    if (cardTitle) {
                        const titleWords = splitHeadingWords(cardTitle);
                        if (titleWords.length) {
                            gsap.fromTo(titleWords,
                                { yPercent: 110, opacity: 0 },
                                {
                                    yPercent: 0,
                                    opacity: 1,
                                    stagger: 0.05,
                                    duration: 0.65,
                                    ease: 'power3.out',
                                    scrollTrigger: {
                                        trigger: card,
                                        start: 'top 80%',
                                        toggleActions: 'play none none reverse'
                                    }
                                }
                            );
                        }
                    }
                    if (cardDesc) {
                        const litWords = splitParagraphLitWords(cardDesc);
                        if (litWords.length) {
                            gsap.fromTo(litWords,
                                { opacity: 0.25 },
                                {
                                    opacity: 1,
                                    stagger: 0.03,
                                    ease: 'none',
                                    scrollTrigger: {
                                        trigger: card,
                                        start: 'top 78%',
                                        end: 'bottom 65%',
                                        scrub: 0.3
                                    }
                                }
                            );
                        }
                    }
                });

                // 10.7. Seção FAQ (#faq): Surgimento em cascata rítmica (Domino Unfold) conforme rola
                const faqCards = gsap.utils.toArray('#faq .faq-card');
                if (faqCards.length) {
                    faqCards.forEach((card, i) => {
                        gsap.fromTo(card,
                            { y: 35, x: i % 2 === 0 ? -20 : 20, opacity: 0, scale: 0.98 },
                            {
                                y: 0,
                                x: 0,
                                opacity: 1,
                                scale: 1,
                                duration: 0.65,
                                ease: 'power3.out',
                                scrollTrigger: {
                                    trigger: card,
                                    start: 'top 90%',
                                    toggleActions: 'play none none reverse'
                                }
                            }
                        );
                    });
                }

                // 10.8. Seção Final CTA: Expansão cinematográfica ligada ao scroll + botões em destaque
                const finalCtaCard = document.querySelector('#main-content > section:last-of-type .glass-card');
                if (finalCtaCard) {
                    gsap.fromTo(finalCtaCard,
                        { y: 60, scale: 0.92, opacity: 0 },
                        {
                            y: 0,
                            scale: 1,
                            opacity: 1,
                            ease: 'power2.out',
                            scrollTrigger: {
                                trigger: finalCtaCard,
                                start: 'top 90%',
                                end: 'top 55%',
                                scrub: 0.4
                            }
                        }
                    );

                    const ctaButtons = finalCtaCard.querySelectorAll('a');
                    if (ctaButtons.length) {
                        gsap.fromTo(ctaButtons,
                            { y: 25, opacity: 0, scale: 0.95 },
                            {
                                y: 0,
                                opacity: 1,
                                scale: 1,
                                stagger: 0.12,
                                duration: 0.7,
                                ease: 'back.out(1.4)',
                                scrollTrigger: {
                                    trigger: finalCtaCard,
                                    start: 'top 70%',
                                    toggleActions: 'play none none reverse'
                                }
                            }
                        );
                    }
                }
            }

});

// === js/ui-interactions.js ===
document.addEventListener("DOMContentLoaded", () => {
        // 4. FAQ ACCORDION INTERATIVO
        // -------------------------------------------------------------
        document.querySelectorAll('.faq-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const answer = btn.nextElementSibling;
                const icon = btn.querySelector('.faq-icon');
                const isHidden = answer.classList.contains('hidden');

                document.querySelectorAll('.faq-answer').forEach(a => a.classList.add('hidden'));
                document.querySelectorAll('.faq-icon').forEach(i => { i.textContent = '+'; i.style.transform = 'rotate(0deg)'; });

                if (isHidden) {
                    answer.classList.remove('hidden');
                    icon.textContent = '−';
                    icon.style.transform = 'rotate(180deg)';
                }
            });
        });

        // -------------------------------------------------------------
        // 5. COUNTDOWN TIMER (PREVISÃO DE ABERTURA DAS INSCRIÇÕES 2027)
        // -------------------------------------------------------------
        const targetDate = new Date('2027-01-05T10:00:00-03:00');
        const daysEl = document.getElementById('hud-days');
        const hoursEl = document.getElementById('hud-hours');
        const minutesEl = document.getElementById('hud-minutes');
        const secondsEl = document.getElementById('hud-seconds');

        function updateCountdown() {
            if (!daysEl || !hoursEl || !minutesEl || !secondsEl) return;
            const diff = Math.max(0, targetDate - new Date());

            const d = Math.floor(diff / (1000 * 60 * 60 * 24));
            const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
            const m = Math.floor((diff / (1000 * 60)) % 60);
            const s = Math.floor((diff / 1000) % 60);

            daysEl.textContent = d < 10 ? '0' + d : String(d);
            hoursEl.textContent = h < 10 ? '0' + h : String(h);
            minutesEl.textContent = m < 10 ? '0' + m : String(m);
            secondsEl.textContent = s < 10 ? '0' + s : String(s);
        }

        if (daysEl) {
            setInterval(updateCountdown, 1000);
            updateCountdown();
        }

        // -------------------------------------------------------------
        // 6. SMOOTH ANCHOR NAVIGATION (INTEGRADA AO LENIS)
        // -------------------------------------------------------------
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                const targetId = this.getAttribute('href');
                if (targetId === '#') return;
                const targetEl = document.querySelector(targetId);
                if (targetEl) {
                    e.preventDefault();
                    if (window.__lenis) {
                        window.__lenis.scrollTo(targetEl, { duration: 1.1 });
                    } else {
                        targetEl.scrollIntoView({ behavior: 'smooth' });
                    }
                }
            });
        });

        // -------------------------------------------------------------

            // 9. ANIMATED STAT COUNTERS ON SCROLL (107 VAGAS & MÉTRICAS)
            // -------------------------------------------------------------
            const vagasSection = document.getElementById('vagas');
            if (vagasSection) {
                const counters = [
                    { id: 'counter-vagas', target: 107, duration: 2.2 },
                    { id: 'counter-especialidades', target: 13, duration: 1.6 },
                    { id: 'counter-gratuito', target: 100, duration: 2.0 }
                ];

                const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

                if (prefersReducedMotion || typeof gsap === 'undefined') {
                    counters.forEach(c => {
                        const el = document.getElementById(c.id);
                        if (el) el.textContent = c.target;
                    });
                } else {
                    // Incremento numerico suave (0 -> target) engatilhado no scroll
                    counters.forEach(c => {
                        const el = document.getElementById(c.id);
                        if (!el) return;
                        const proxy = { val: 0 };
                        gsap.to(proxy, {
                            val: c.target,
                            duration: c.duration,
                            ease: 'power2.out',
                            scrollTrigger: {
                                trigger: '#vagas',
                                start: 'top 85%',
                                once: true
                            },
                            onUpdate: () => {
                                el.textContent = Math.round(proxy.val);
                            }
                        });
                    });
                }
            }

            // -------------------------------------------------------------
});

// === js/aurora-bg.js ===
/**
 * UFF Medicina 2027 - Background Aurora WebGL2 (React Bits portado para Vanilla JS)
 * Otimizado para zero impacto em LCP/Hero e baixo uso de GPU.
 */
(() => {
    const MAX_STOPS = 5;
    const MAX_LAYERS = 3;
    const INTRO_SECONDS = 2.4;

    const VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

    const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;
uniform vec2 uResolution;
uniform float uTime;
uniform vec3 uStops[${MAX_STOPS}];
uniform int uStopCount;
uniform float uAmplitude;
uniform float uBlend;
uniform float uHeight;
uniform float uScale;
uniform float uGlow;
uniform float uBrightness;
uniform int uLayers;
uniform float uFlip;
uniform vec3 uPointer;
uniform float uReveal;
uniform float uOpacity;
uniform float uLightMode;
out vec4 outColor;

vec3 permute(vec3 x) {
  return mod(((x * 34.0) + 1.0) * x, 289.0);
}

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float smootherstep(float edge0, float edge1, float x) {
  float t = clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

vec3 oklabToLinear(vec3 c) {
  float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  l = l * l * l;
  m = m * m * m;
  s = s * s * s;
  return vec3(
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
  );
}

vec3 toSrgb(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
}

vec3 ramp(float t) {
  float x = clamp(t, 0.0, 1.0) * float(uStopCount - 1);
  int i = int(min(floor(x), float(uStopCount - 2)));
  float f = x - float(i);
  f = f * f * (3.0 - 2.0 * f);
  vec3 lch = mix(uStops[i], uStops[i + 1], f);
  lch.x = mix(lch.x, min(lch.x, 0.7), uLightMode);
  return toSrgb(oklabToLinear(vec3(lch.x, lch.y * cos(lch.z), lch.y * sin(lch.z))));
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

void main() {
  vec2 frag = gl_FragCoord.xy;
  float y = 1.0 - frag.y / uResolution.y;
  y = mix(y, 1.0 - y, uFlip);
  float u = frag.x / uResolution.x;
  float X = (frag.x - uResolution.x * 0.5) / uResolution.y;
  float t = uTime;
  float reach = uPointer.z * exp(-pow((X - uPointer.x) / 0.38, 2.0));

  vec3 glow = vec3(0.0);
  float cover = 0.0;
  for (int k = 0; k < ${MAX_LAYERS}; k++) {
    if (k >= uLayers) break;
    float layer = float(k);
    float seed = layer * 13.7;
    float pace = t * (1.0 - layer * 0.18);
    float warp = snoise(vec2(X * 0.45 * uScale + pace * 0.02 + seed, pace * 0.05 + seed));
    float wave = snoise(vec2(X * 0.75 * uScale + warp * 0.35 - pace * 0.03 + seed, pace * 0.07 - seed)) * 0.72
      + snoise(vec2(X * 1.6 * uScale + warp * 0.5 + pace * 0.04 - seed, pace * 0.1 + seed * 0.5)) * 0.28;
    float hem = uHeight + layer * 0.07 + wave * 0.15 * uAmplitude;
    hem += reach * 0.08 * (layer < 0.5 ? 1.0 : 0.4);
    hem = mix(-0.25, hem, uReveal);

    float soft = (0.04 + uBlend * 0.16) * (1.0 + layer * 0.9);
    float rise = hem - y;
    float low = -soft - uGlow * 0.14;
    float high = 0.26 + soft * 0.6;
    float body = pow(smootherstep(low, high, rise), 1.5 + uGlow * 0.6);
    float lobes = 0.86 + 0.14 * snoise(vec2(X * 0.9 * uScale - pace * 0.025 + seed, y * 0.3 + pace * 0.04));
    float alpha = body * lobes * (layer < 0.5 ? 1.0 : 0.32 / layer);
    alpha = clamp(alpha * (1.0 + reach * 0.25 * smootherstep(0.9, 0.0, abs(y - hem))), 0.0, 1.0);

    vec3 tint = ramp(u + 0.05 * sin(pace * 0.08 + layer * 2.3) + layer * 0.1 + max(rise, 0.0) * 0.05);
    glow = 1.0 - (1.0 - glow) * (1.0 - tint * alpha);
    cover = 1.0 - (1.0 - cover) * (1.0 - alpha);
  }

  float fade = smootherstep(0.0, 0.7, uReveal) * uOpacity;
  float strength = clamp(uBrightness, 0.0, 2.0);
  glow *= fade * min(strength, 1.0);
  cover *= fade * min(strength, 1.0);
  glow = 1.0 - pow(1.0 - glow, vec3(max(strength, 1.0)));
  float dither = (hash(frag) - 0.5) / 255.0;

  if (uLightMode > 0.5) {
    vec3 tint = cover > 0.0001 ? glow / cover : vec3(0.0);
    cover *= smootherstep(0.0, 0.25, cover);
    float alpha = cover * 0.7;
    outColor = vec4(tint * alpha + dither, clamp(alpha + dither, 0.0, 1.0));
    return;
  }
  outColor = vec4(glow + dither, clamp(cover + dither, 0.0, 1.0));
}`;

    const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

    const toOklch = (rgb) => {
        const [r, g, b] = rgb.map((c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)));
        const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
        const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
        const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
        const lab = [
            0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
            1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
            0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s
        ];
        return [lab[0], Math.hypot(lab[1], lab[2]), Math.atan2(lab[2], lab[1])];
    };

    const unwrapHues = (stops) => {
        const known = stops.findIndex((stop) => stop[1] > 0.02);
        const anchor = known === -1 ? 0 : stops[known][2];
        let previous = anchor;
        return stops.map((stop) => {
            let hue = stop[1] > 0.02 ? stop[2] : previous;
            while (hue - previous > Math.PI) hue -= Math.PI * 2;
            while (hue - previous < -Math.PI) hue += Math.PI * 2;
            previous = hue;
            return [stop[0], stop[1], hue];
        });
    };

    const compile = (gl, type, source) => {
        const shader = gl.createShader(type);
        if (!shader) return null;
        gl.shaderSource(shader, source);
        gl.compileShader(shader);
        if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
        gl.deleteShader(shader);
        return null;
    };

    const link = (gl) => {
        const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
        const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
        const program = gl.createProgram();
        if (!vertex || !fragment || !program) return null;
        gl.attachShader(program, vertex);
        gl.attachShader(program, fragment);
        gl.bindAttribLocation(program, 0, 'aPosition');
        gl.linkProgram(program);
        gl.deleteShader(vertex);
        gl.deleteShader(fragment);
        if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
            gl.deleteProgram(program);
            return null;
        }
        const uniforms = {};
        const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
        for (let i = 0; i < count; i++) {
            const info = gl.getActiveUniform(program, i);
            if (info) uniforms[info.name.replace('[0]', '')] = gl.getUniformLocation(program, info.name);
        }
        return { program, uniforms };
    };

    function initAuroraBackground() {
        const container = document.getElementById('aurora-bg');
        const canvas = document.getElementById('aurora-canvas');
        if (!container || !canvas) return;

        const gl = canvas.getContext('webgl2', {
            alpha: true,
            premultipliedAlpha: true,
            antialias: false,
            depth: false,
            stencil: false,
            powerPreference: 'low-power'
        });
        if (!gl) return;

        const program = link(gl);
        if (!program) return;
        const u = program.uniforms;

        const buffer = gl.createBuffer();
        const vao = gl.createVertexArray();
        gl.bindVertexArray(vao);
        gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

        const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
        const isCoarsePointer = window.matchMedia?.('(pointer: coarse)').matches ?? false;

        // Cores oficiais do projeto UFF Medicina 2027
        const colorStops = ['#023D28', '#006843', '#009E5E', '#10B981', '#023D28'];
        const settings = {
            amplitude: 1.45,
            blend: 0.36,
            height: 0.65,
            speed: 1.1,
            glow: 0.68,
            scale: 0.65,
            brightness: 0.82,
            layers: 1,
            flip: 0,
            opacity: 0.55,
            lightMode: 0,
            mouseInteraction: !isCoarsePointer
        };

        const probe = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
        const parse = (value) => {
            if (!probe) return [0, 0.4, 0.26];
            probe.clearRect(0, 0, 1, 1);
            probe.fillStyle = '#ffffff';
            probe.fillStyle = value;
            probe.fillRect(0, 0, 1, 1);
            const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
            return [r / 255, g / 255, b / 255];
        };

        const palette = new Float32Array(MAX_STOPS * 3);
        unwrapHues(colorStops.map((v) => toOklch(parse(v)))).forEach((stop, index) => palette.set(stop, index * 3));

        const view = { width: 1, height: 1 };
        const pointer = { x: 0, y: 0, inside: false };
        const state = {
            clock: 0,
            px: 0,
            py: 0.5,
            reach: 0,
            reveal: reduce ? 1 : 0
        };

        let raf = 0;
        let last = 0;
        let isBelowHero = window.scrollY > window.innerHeight * 0.15;

        const render = () => {
            gl.viewport(0, 0, canvas.width, canvas.height);
            gl.useProgram(program.program);
            gl.bindVertexArray(vao);
            gl.uniform2f(u.uResolution, canvas.width, canvas.height);
            gl.uniform1f(u.uTime, state.clock);
            gl.uniform3fv(u.uStops, palette);
            gl.uniform1i(u.uStopCount, colorStops.length);
            gl.uniform1f(u.uAmplitude, settings.amplitude);
            gl.uniform1f(u.uBlend, settings.blend);
            gl.uniform1f(u.uHeight, settings.height);
            gl.uniform1f(u.uScale, settings.scale);
            gl.uniform1f(u.uGlow, settings.glow);
            gl.uniform1f(u.uBrightness, settings.brightness);
            gl.uniform1i(u.uLayers, settings.layers);
            gl.uniform1f(u.uFlip, settings.flip);
            gl.uniform3f(u.uPointer, state.px, state.py, state.reach);
            gl.uniform1f(u.uReveal, 1 - Math.pow(1 - state.reveal, 3));
            gl.uniform1f(u.uOpacity, settings.opacity);
            gl.uniform1f(u.uLightMode, settings.lightMode);
            gl.drawArrays(gl.TRIANGLES, 0, 3);
        };

        const canAnimate = () => !document.hidden && !reduce && isBelowHero;

        const frame = (now) => {
            raf = 0;
            if (!canAnimate()) {
                last = 0;
                return;
            }
            const dt = last ? clamp((now - last) / 1000, 0.0005, 0.05) : 1 / 60;
            last = now;
            state.clock += dt * settings.speed;

            const engaged = settings.mouseInteraction && pointer.inside;
            const follow = 1 - Math.exp(-dt / 0.6);
            if (engaged) {
                const tx = (pointer.x - view.width / 2) / view.height;
                const ty = settings.flip ? 1 - pointer.y / view.height : pointer.y / view.height;
                state.px += (tx - state.px) * follow;
                state.py += (ty - state.py) * follow;
            }
            state.reach += ((engaged ? 1 : 0) - state.reach) * (1 - Math.exp(-dt / (engaged ? 0.9 : 1.4)));
            if (state.reveal < 1) state.reveal = Math.min(1, state.reveal + dt / INTRO_SECONDS);

            render();
            raf = requestAnimationFrame(frame);
        };

        const wake = () => {
            if (!raf && canAnimate()) {
                last = 0;
                raf = requestAnimationFrame(frame);
            }
        };

        const resize = () => {
            const width = Math.max(1, container.clientWidth);
            const height = Math.max(1, container.clientHeight);
            // Cap DPR para manter 60fps suaves sem sobrecarregar GPU
            const ratio = Math.min(window.devicePixelRatio || 1, isCoarsePointer ? 1 : 1.15);
            view.width = width;
            view.height = height;
            canvas.width = Math.max(1, Math.round(width * ratio));
            canvas.height = Math.max(1, Math.round(height * ratio));
            render();
            wake();
        };

        if (settings.mouseInteraction) {
            window.addEventListener('pointermove', (event) => {
                if (!isBelowHero) return;
                pointer.x = event.clientX;
                pointer.y = event.clientY;
                pointer.inside = true;
            }, { passive: true });
            document.documentElement.addEventListener('pointerleave', () => {
                pointer.inside = false;
            });
        }

        window.addEventListener('scroll', () => {
            const next = window.scrollY > window.innerHeight * 0.15;
            if (next !== isBelowHero) {
                isBelowHero = next;
                if (isBelowHero) wake();
            }
        }, { passive: true });

        document.addEventListener('visibilitychange', () => {
            if (!document.hidden) wake();
        });

        if ('ResizeObserver' in window) {
            new ResizeObserver(resize).observe(container);
        } else {
            window.addEventListener('resize', resize, { passive: true });
        }

        resize();
    }

    document.addEventListener('DOMContentLoaded', () => {
        if ('requestIdleCallback' in window) {
            requestIdleCallback(initAuroraBackground, { timeout: 400 });
        } else {
            setTimeout(initAuroraBackground, 150);
        }
    });
})();
